import { part as p, history, source, before, sample, s, op } from './authoring.mjs';
import { table, flow, q, tf, challenge } from './design-authoring.mjs';
import { sqlLesson, sqlExample as ex, sqlChallenge as exercise } from './sql-authoring.mjs';

const S = (title, path) => source(title, path);
const codd = S('Codd’s 1970 relational model paper', 'https://research.ibm.com/publications/a-relational-model-of-data-for-large-shared-data-banks');
const sqlite = (title, page) => S(title, `https://www.sqlite.org/${page}.html`);
const postgres = (title, page) => S(title, `https://www.postgresql.org/docs/current/${page}.html`);
const build = (title, problem, challenge, sources, cases, recipe, why, limitation, hints) => ({title,problem,challenge,sources,cases,recipe,why,limitation,hints,extras:[],draftVersion:1});
const output = value => JSON.stringify(value);
const resultTest = expected => `import json\nassert [list(r) for r in rows] == json.loads(${JSON.stringify(output(expected))})`;
const variant = (setup, expected) => `import json\nassert [list(r) for r in query_rows(sql, setup_sql + ${JSON.stringify(setup)})] == json.loads(${JSON.stringify(output(expected))})`;
const rejects = statement => `import sqlite3\ndb.execute("SAVEPOINT invalid_input")\ntry:\n    db.execute(${JSON.stringify(statement)})\nexcept sqlite3.IntegrityError:\n    pass\nelse:\n    raise AssertionError("The table accepted a forbidden record")\nfinally:\n    db.execute("ROLLBACK TO invalid_input")\n    db.execute("RELEASE invalid_input")`;
const readings = `CREATE TABLE readings(id INTEGER PRIMARY KEY,asset_id TEXT NOT NULL,recorded_at TEXT NOT NULL,value REAL NOT NULL);\nINSERT INTO readings VALUES(1,'P7','2026-01-01',20),(2,'P7','2026-01-02',24),(3,'P8','2026-01-02',80),(4,'P7','2026-01-03',26),(5,'P8','2026-01-04',85);`;
function reading(experimentTitle, experimentIntro, connectionTitle, practiceTitle, outputLabel) { return {experimentTitle,experimentIntro,connectionTitle,practiceTitle,outputLabel,exampleNote:'Invented maintenance records. SQL programs run in an isolated SQLite database; the workshop illustrates the operation with records rather than parsing SQL.'}; }

const schemaSolution = `CREATE TABLE equipment(\n  id TEXT PRIMARY KEY NOT NULL,\n  model TEXT NOT NULL,\n  retired INTEGER NOT NULL CHECK(retired IN (0,1)),\n  cost_cents INTEGER NOT NULL CHECK(cost_cents >= 0)\n) STRICT;\nINSERT INTO equipment(id,model,retired,cost_cents) SELECT id,model,retired,cost_cents FROM incoming;\nSELECT id,model,retired,cost_cents FROM equipment ORDER BY id;`;
const schemaSetup = `CREATE TABLE incoming(id TEXT,model TEXT,retired INTEGER,cost_cents INTEGER);\nINSERT INTO incoming VALUES('P7','M2',0,12550),('P8','M3',1,9900);`;
const schema = sqlLesson({
  id:'sql-schema-design',title:'What Does One Equipment Record Promise?',topic:'Designing Reliable Tables',
  blurb:'A column called cost can hold cents, pounds or an unexplained string. Give the maintenance team a table whose identities and units mean the same thing on every row.',
  openingTitle:'P7 Is an Identifier. Why Did the Import Treat It as a Measurement?',
  opening:['Botie receives a spreadsheet of equipment. One file uses asset labels, another uses row positions, and the cost column has no unit. We can write a SELECT over those values, but it cannot decide what the authors meant.','A schema records what a row represents and what its fields promise. We will design an equipment table, then use the database to reject records that violate that promise.'],
  prerequisites:[before('Table grain and joins','sql-join-grain'),before('Null values','sql-null')],
  history:history('Keeping the Meaning of a Record Separate from Its Storage', [codd,sqlite('SQLite type affinity','datatype3'),sqlite('STRICT tables','stricttables')], 'Codd’s 1970 paper argued for a relational description of data that did not make users depend on physical storage arrangements. A logical table needs a stable interpretation even when the database changes how it stores its rows. Our equipment register uses that distinction: an asset identity should survive a new sort order or index.', 'SQLite later made a deliberate choice to support flexible value typing. Its STRICT table option, introduced in version 3.37.0 in 2021, provides stronger type enforcement for applications that want it. The browser exercises use SQLite 3.39-compatible syntax and make those dialect choices explicit.'),
  reading:reading('Which incoming records fit the declared fields?','Connect the field contract before deciding which record IDs need repair.','A schema makes the row’s meaning testable','Practice. Create the equipment register','Rejected record IDs'),
  intuition:[table('Decide what each column means before picking a type','One row represents one equipment asset, including retired assets.',['Field','Meaning','Representation'],[['id','Stable asset identity','Text, for example P7'],['model','Model designation','Required text'],['retired','Whether the asset left service','Integer 0 or 1'],['cost_cents','Acquisition cost in cents','Nonnegative integer']], 'An identifier can contain digits without being a quantity to average.')],
  technicalPart:3,checkpointAfter:2,
  parts:[
    p('Choose the row’s grain and identity','Our equipment table has one row per asset. A visit table would instead have one row per visit. Putting several visits into extra columns on an equipment row would mix those grains and make another visit require a schema change.\n\nChoose a key that identifies the asset across imports. A spreadsheet row number changes when rows are sorted. A serial number may be a useful natural key if the business guarantees its uniqueness and stability. A generated surrogate key can provide stable internal identity while a separate unique constraint preserves a business identifier.',null,'A generated key does not remove the need to define which real-world duplicates are forbidden.'),
    p('Write the unit into the contract','Cost in cents can be stored as an integer when the business works in one currency and fixed minor units. A currency field is needed if that assumption changes. A temperature needs a unit and a measurement time. Neither choice follows from calling a column REAL.\n\nDecide how unknown values differ from zero, and which values may be absent. A retired asset is still an asset, so retaining its row preserves references from earlier inspections. Our retired flag records that state without reusing its identity for another pump.',null,'The schema is an agreement about meaning as well as storage.'),
    p('SQLite affinity is not a general type guarantee','In an ordinary SQLite table, a declared type usually gives the column an affinity that guides conversion. It does not generally forbid another storage class. STRICT tables narrow the allowed declared types and require compatible values, although lossless conversions may still occur.\n\nUse TEXT for our identifiers, INTEGER for the flag and cents, and explicit NOT NULL where absence is invalid. REAL is floating point, so it does not provide exact decimal-money arithmetic. PostgreSQL has different type rules and offers NUMERIC for exact decimal quantities. Porting a schema requires reviewing those differences.',null,'We use STRICT here because the exercise asks the database to reject incompatible values. The workshop checks already-decoded values without simulating SQLite conversion.',[ex('Give a small asset register declared types','Create one row and ask SQLite how it stored its values.','',`CREATE TABLE asset_example(id TEXT NOT NULL, cost_cents INTEGER NOT NULL) STRICT;\nINSERT INTO asset_example VALUES('P3',850);\nSELECT id,typeof(id),cost_cents,typeof(cost_cents) FROM asset_example;`,output([['P3','text',850,'integer']]),'The identifier remains text while cents remain an integer. Type still does not tell us which currency the cents represent.')]),
    p('Declare the complete table','CREATE TABLE lists each column and its constraints. PRIMARY KEY identifies a row; NOT NULL forbids a missing required field. CHECK adds the domain rule that the retired flag is either zero or one and that cost is nonnegative.\n\nSQLite has historical exceptions around nullable primary keys in ordinary rowid tables. Use explicit NOT NULL for portable intent rather than depending on that behaviour. INTEGER PRIMARY KEY has special rowid behaviour in SQLite and can generate an ID when NULL is inserted. Our text asset key is supplied by the application.',null,'Use an explicit INSERT column list. It documents the mapping and makes later schema changes less likely to reorder values silently.'),
    p('Inspect a schema instead of guessing it','PRAGMA table_info(equipment) reports declared columns in SQLite, while sqlite_schema contains schema definitions. Other engines provide information_schema or their own catalogues. These are useful when diagnosing an import that worked against an older schema.\n\nCREATE TABLE AS SELECT can be convenient for an analytical copy, but it does not preserve the original table’s keys and constraints in SQLite. A copied dataset and a durable application table can therefore have very different guarantees even when their visible rows match.',null,'The challenge tests future inserts as well as the initial displayed rows.'),
    p('Treat schema changes as data changes','Adding a required field to a populated table raises a question: what value belongs on existing rows? A default is only appropriate when it represents a defensible meaning. Inventing zero to satisfy NOT NULL can corrupt later analysis.\n\nPlan a migration that adds or rebuilds the structure, converts and checks existing data, and updates readers and writers in a controlled order. Keep a recovery path and test with representative old records. A fresh empty exercise database avoids deployment concerns; it does not demonstrate a safe migration on a live service.',null,'Botie can now reject an incompatible record, but we still need rules connecting one table to another.'),
  ],
  checkpoint:[q('One equipment row represents one physical asset. Inspection visits can occur many times for that asset.','What belongs in a separate visit table?',['One row per inspection with an asset reference','A new equipment column for every future visit','A new asset identity whenever it is inspected'],0,'A visit and an asset have different grains.'),tf('An asset identifier is the text value 0007 and leading zeros matter.','Treating it as an integer can discard meaningful representation.',true,'An identifier is not necessarily a numeric measurement.')],
  quiz:[q('A SQLite table was created with CREATE TABLE AS SELECT from a constrained source.','What should you verify before treating it as the application register?',['Its keys and constraints, which are not automatically copied','Only whether its first two rows match','Whether SELECT statements use uppercase'],0,'Matching data does not establish matching schema guarantees.'),tf('The column declaration is REAL and the business needs exact currency cents.','The type declaration alone guarantees exact decimal-money arithmetic.',false,'REAL uses floating point. Integer minor units or a suitable exact decimal type need a deliberate domain choice.')],
  practice:[exercise('Can the register reject malformed equipment records?',['Create equipment with id TEXT primary key and explicitly not null, model TEXT not null, retired INTEGER not null restricted to 0 or 1, and cost_cents INTEGER not null and nonnegative. Use a STRICT table. Copy every incoming record using an explicit column mapping. Finish with id, model, retired, cost_cents ordered by id.'],schemaSetup,'-- Create the equipment table, then copy the incoming rows.\n',schemaSolution,output([['P7','M2',0,12550],['P8','M3',1,9900]]),['A type and a domain restriction answer different questions. INTEGER still permits values other than 0 and 1.','Make the text primary key explicitly NOT NULL.'],[['Imported rows',resultTest([['P7','M2',0,12550],['P8','M3',1,9900]])],['Duplicate identity',rejects("INSERT INTO equipment VALUES('P7','M9',0,2)")],['Unknown identity',rejects("INSERT INTO equipment VALUES(NULL,'M9',0,2)")],['Invalid flag and incompatible storage',rejects("INSERT INTO equipment VALUES('P9','M9',2,2)")+'\n'+rejects("INSERT INTO equipment VALUES('P9','M9',0,'expensive')")],['A new valid import',variant("INSERT INTO incoming VALUES('P4','M4',0,0);",[['P4','M4',0,0],['P7','M2',0,12550],['P8','M3',1,9900]])]])],
  build:build('Inspect equipment fields before accepting a record','An import includes fields whose values do not fit the agreed equipment contract.','Connect the incoming rows to the field checker, then return the IDs whose checks fail.',{rows:'Incoming equipment',contract:'Expected value types'},[sample('A cost arrived as a word',{rows:[{id:'P7',model:'M2',cost_cents:250},{id:'P8',model:'M3',cost_cents:'unknown'}],contract:{id:'text',model:'text',cost_cents:'integer'}},['P8']),sample('Both records use integer cents',{rows:[{id:'P7',model:'M2',cost_cents:250},{id:'P8',model:'M3',cost_cents:0}],contract:{id:'text',model:'text',cost_cents:'integer'}},[]),sample('A model is absent',{rows:[{id:'P2',model:null,cost_cents:25}],contract:{id:'text',model:'text',cost_cents:'integer'}},['P2'])],op('ssFailedIds',op('ssCheckTypes',s('rows'),s('contract'))),'The row remains identifiable when a field fails, so the import can be repaired.','This checker validates decoded values. SQLite affinity and STRICT lossless conversions are taught in the SQL program, not simulated here.',['Check each named field before collecting the rejected IDs.']),
});

const constraintsSetup = `CREATE TABLE assets(id TEXT PRIMARY KEY NOT NULL); INSERT INTO assets VALUES('P7'),('P8');`;
const constraintsSolution = `CREATE TABLE jobs(\n id TEXT PRIMARY KEY NOT NULL,\n asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,\n minutes INTEGER NOT NULL CHECK(minutes >= 0),\n status TEXT NOT NULL CHECK(status IN ('open','done'))\n) STRICT;\nINSERT INTO jobs VALUES('J1','P7',30,'open');\nSELECT id,asset_id,minutes,status FROM jobs ORDER BY id;`;
const constraints = sqlLesson({
 id:'sql-constraints',title:'Can a Job Refer to a Pump We Have Never Recorded?',topic:'Designing Reliable Tables',blurb:'A row can have the right types and still contain an impossible reference. Put identity, domain and relationship rules at the database boundary.',openingTitle:'The Job Exists, but Its Asset Does Not',opening:['The maintenance team opens an inspection for P99. The job has a valid-looking ID and duration, but P99 is absent from the equipment register. A later join quietly loses the job.','We need the database to preserve the relationship while accepting writes from every application that uses it. Constraints make those rules part of the table rather than a convention in one import script.'],prerequisites:[before('Schema design','sql-schema-design')],
 history:history('Preserving Relationships Across Several Writers',[codd,sqlite('Foreign-key enforcement in SQLite','foreignkeys'),postgres('SQL constraints','ddl-constraints')],'Relational tables let records be connected through values instead of application-specific pointers. That independence makes relationship rules important: any writer can otherwise introduce a child record whose parent is absent. Foreign keys put that relationship check in the database.', 'SQLite’s documentation records foreign-key enforcement beginning in version 3.6.19 in 2009. It must be enabled for each connection in the configuration used here. The browser runner enables it before executing your statements. Merely seeing REFERENCES in a schema is insufficient evidence that a particular connection enforces it.'),
 reading:reading('Which proposed jobs violate the table contract?','Check duration and parent identity together, then retain the failing job IDs.','A valid field can still point to a missing parent','Practice. Protect job records with constraints','Rejected job IDs'),
 intuition:[table('Different constraints answer different questions','All of these apply to the same proposed job.',['Rule','Question','Example rejected'],[['Primary key','Which job is this?','Reusing J1'],['NOT NULL','Must duration be present?','Unknown duration'],['CHECK','Is duration in the allowed domain?','Negative minutes'],['Foreign key','Does its asset exist?','P99 absent from assets']], 'A positive duration does not establish an asset reference.')],technicalPart:3,checkpointAfter:2,
 parts:[p('Let the database check every writer','A form can validate an asset ID, but a batch importer may bypass the form. A constraint checks the data at the shared write boundary. It also protects against two writers that both passed a preliminary application check before either committed.\n\nKeep friendly validation in the interface so users can repair mistakes. Treat database constraint failures as expected error outcomes too. The interface cannot safely assume that the state remained unchanged between its first check and its write.',null,'The database rejects the violating change; the application still needs to explain which request failed.'),p('Separate missing values from invalid values','A CHECK expression rejects a row when it evaluates to false. An unknown result from NULL does not act like false in this setting. CHECK(minutes >= 0) therefore needs NOT NULL when every job must have a duration.\n\nA UNIQUE constraint handles duplicate keys, but null treatment varies by dialect and declaration. Specify the intended null policy separately. Our job IDs and asset references must always exist, so both are explicitly not null.',null,'A constraint is a precise predicate. Read its NULL behaviour rather than relying on the wording of the column name.'),p('Make the parent key explicit','REFERENCES assets(id) connects the child’s asset_id to the parent’s declared unique identity. Insert the parent before an immediately checked child. The child column’s type and representation should match the identifier contract.\n\nThe SQLite runner enables PRAGMA foreign_keys = ON before starting learner work. Changing this pragma inside an active transaction does not enable enforcement for that transaction. Production connections need deliberate initialisation and a verification check.',null,'A foreign key establishes existence. It does not establish that the current user is allowed to use that asset.',[ex('Attach an inspection to an existing asset','The child row stores the parent identity once.',constraintsSetup,`CREATE TABLE visits(id TEXT PRIMARY KEY NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id));\nINSERT INTO visits VALUES('V3','P8');\nSELECT v.id,a.id FROM visits v JOIN assets a ON a.id=v.asset_id;`,output([['V3','P8']]),'The join can resolve the reference because the parent was inserted first.')]),p('Decide what deleting a parent should mean','Deleting an asset with historical jobs may need to be forbidden. ON DELETE RESTRICT expresses that policy here. CASCADE can be appropriate when dependent rows have no independent meaning, but it can also erase useful history if chosen casually.\n\nSET NULL requires a nullable child reference and changes the meaning of the relationship. Often an equipment register should mark an asset retired rather than delete it. Choose based on the records’ lifetimes and audit requirements.',null,'A referential action is a business decision that the database executes automatically.'),p('Some rules involve more than one row','A row-level CHECK can validate minutes or a status. Rules such as one active assignment per asset may need a unique or partial unique index. More complex cross-row conditions can require carefully designed transactions or triggers.\n\nDo not hide a lookup of another table inside an apparently local check and assume every future change will revalidate it. Use the database mechanisms whose enforcement scope matches the invariant. PostgreSQL and SQLite differ in supported forms, so inspect the chosen dialect.',null,'Constraints are strongest when their intended scope is easy to state and test.'),p('Test the rejected writes as well as the accepted one','The exercise inserts one valid job, then its tests try a missing parent, a duplicate key, a negative duration and a null duration. Each failure reveals a different missing constraint.\n\nAfter a failed statement, inspect transaction state before deciding whether to continue or roll back. Engines and conflict policies differ. Our test harness isolates each attempted invalid insert in a savepoint so a rejection does not contaminate the next test.',null,'A display containing one good row cannot prove that the next bad row will be rejected.')],
 checkpoint:[q('A table declares minutes INTEGER CHECK(minutes >= 0), with no NOT NULL. The proposed minutes value is NULL.','What additional rule is needed if every duration must be supplied?',['NOT NULL','ORDER BY minutes','A larger maximum duration'],0,'The CHECK expression can evaluate to unknown. NOT NULL independently forbids absence.'),tf('The database enforces a foreign key from jobs.asset_id to assets.id.','A job referencing an absent asset is rejected.',true,'The foreign key protects the declared relationship at the write boundary.')],quiz:[q('Assets have historical jobs that must remain interpretable. An asset leaves service.','Which policy preserves that history without deleting related jobs?',['Retain the asset and mark it retired','Always cascade-delete its jobs','Remove the asset key from every query'],0,'Retirement preserves the referenced identity while recording its changed state.'),tf('A valid foreign key points to an asset belonging to another customer.','The reference alone proves the current user is authorised to access it.',false,'Existence and authorisation require different checks.')],
 practice:[exercise('Can a job table defend its relationship to the register?',['Create jobs exactly with the four fields shown in the starter comment: text id primary key and not null; asset_id text not null referencing assets(id) with ON DELETE RESTRICT; minutes integer not null and nonnegative; status text not null limited to open or done. Use STRICT. Insert J1 for P7 with 30 minutes and status open, then SELECT all four fields ordered by id.'],constraintsSetup,'-- jobs(id, asset_id, minutes, status)\n',constraintsSolution,output([['J1','P7',30,'open']]),['NOT NULL and CHECK are separate declarations.','The referenced parent column must identify an asset uniquely.'],[['Valid job',resultTest([['J1','P7',30,'open']])],['Missing parent',rejects("INSERT INTO jobs VALUES('J2','P99',2,'open')")],['Duration contract',rejects("INSERT INTO jobs VALUES('J2','P8',NULL,'open')")+'\n'+rejects("INSERT INTO jobs VALUES('J2','P8',-1,'open')")],['Referenced parent remains',rejects("DELETE FROM assets WHERE id='P7'")],['Invalid status',rejects("INSERT INTO jobs VALUES('J2','P8',2,'waiting maybe')")]])],
 build:build('Reject impossible maintenance jobs','Proposed jobs need an existing asset and a usable duration.','Apply the joint duration and parent check, then report failed job IDs.',{jobs:'Proposed jobs',assets:'Registered asset IDs'},[sample('One job points to an absent pump',{jobs:[{id:'J1',asset_id:'P7',minutes:20},{id:'J2',asset_id:'P99',minutes:10}],assets:['P7','P8']},['J2']),sample('The parent is added but duration is missing',{jobs:[{id:'J1',asset_id:'P7',minutes:null},{id:'J2',asset_id:'P99',minutes:10}],assets:['P7','P99']},['J1']),sample('Zero minutes is permitted',{jobs:[{id:'J3',asset_id:'P8',minutes:0}],assets:['P8']},[])],op('ssFailedIds',op('ssConstraintCheck',s('jobs'),s('assets'))),'Membership and value checks operate on the same record before its identity is accepted.','The widget illustrates selected invariants. The SQL table additionally enforces uniqueness and database-level relationships.',['Check the parent list and the duration before collecting failures.']),
});

const normalSetup=`CREATE TABLE flat_jobs(job_id TEXT,asset_id TEXT,model TEXT,site TEXT,minutes INTEGER);\nINSERT INTO flat_jobs VALUES('J1','P7','M2','north',20),('J2','P7','M2','north',30),('J3','P8','M3','south',15);`;
const normalSolution=`CREATE TABLE assets(id TEXT PRIMARY KEY NOT NULL,model TEXT NOT NULL,site TEXT NOT NULL);\nCREATE TABLE jobs(id TEXT PRIMARY KEY NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),minutes INTEGER NOT NULL);\nINSERT INTO assets SELECT DISTINCT asset_id,model,site FROM flat_jobs;\nINSERT INTO jobs SELECT job_id,asset_id,minutes FROM flat_jobs;\nSELECT j.id,a.id,a.model,a.site,j.minutes FROM jobs j JOIN assets a ON a.id=j.asset_id ORDER BY j.id;`;
const normalization=sqlLesson({id:'sql-normalization',title:'Why Must a Pump Move Be Edited on Every Job?',topic:'Designing Reliable Tables',blurb:'Repeated asset details make updates disagree. Find which identity determines each fact and give that fact one deliberate home.',openingTitle:'P7 Is in Two Places According to the Same Database',opening:['The maintenance spreadsheet repeats each pump’s model and site on every job. When P7 moves, one row is updated and another still says the old site. Which row should Botie trust?','We can separate facts about an asset from facts about an inspection. The useful question is what determines each value, not how many tables we can create.'],prerequisites:[before('Constraints','sql-constraints'),before('Join grain','sql-join-grain')],history:history('Reducing Facts That Have to Be Updated Together',[codd,S('IBM: Relational design considerations','https://research.ibm.com/publications/considerations-in-developing-a-design-tool-for-a-relational-dbms')],'Relational design made it possible to describe data independently of a file’s arrangement. It also raised a design problem: several table layouts can represent the same apparent facts while behaving differently under updates. Work on dependencies and normal forms addressed those redundancies.','Our repeated pump-site example shows an update anomaly directly. Splitting the records helps only if the decomposition preserves the facts and supports the rules the application must enforce. A smaller table is not automatically a better design.'),reading:reading('Which asset has conflicting site facts?','Group site values by asset identity, check whether each group has one value, and retain the conflicting IDs.','Use dependencies to choose where a fact belongs','Practice. Separate assets from their jobs','Conflicting determinant IDs'),intuition:[table('The same asset fact appears on several job rows','A site update changes only one repeated copy.',['Job','Asset','Recorded site'],[['J1','P7','north'],['J2','P7','south'],['J3','P8','south']],'If the table means current site, the two P7 rows disagree. If it means site at inspection time, the differing sites may be correct and need explicit timestamps.')],technicalPart:3,checkpointAfter:2,parts:[p('First decide whether the repeated fact means now or then','An asset’s current site belongs to its current register entry. Its site at the time of an inspection is a historical fact about that event. Moving an asset should not rewrite history.\n\nWe assume the repeated site column in this lesson means current site. That makes its disagreement a problem. If the intended meaning were site at inspection, the design would need an event-time snapshot or a versioned history instead. Normalisation cannot resolve an ambiguous business definition for us.',null,'Name the temporal meaning before deciding whether values are redundant.'),p('A determinant identifies the dependent fact','Within our stated rules, asset_id determines model and current site. We write that dependency as asset_id → model, site. Job_id determines asset_id and minutes. These are rules about all permitted records, not claims established by a lucky small sample.\n\nThe workshop groups site values by asset ID. Several distinct values refute the current-site dependency in that sample. Finding only one value does not prove the dependency for future data; the domain contract and constraints still matter.',null,'A dependency explains why changing one asset fact should not require editing several unrelated job rows.'),p('Separate the asset facts from the job facts','Create assets with one row per asset and jobs with one row per job. Store asset_id in jobs as a foreign key. A join reconstructs the current display when it is needed.\n\nThe exercise copies distinct consistent asset facts from flat_jobs, then copies the job-specific facts. If source rows disagree about an asset, blindly choosing MIN(site) would conceal the disagreement. Repair or quarantine the conflict before migration. A primary-key violation during the copy is a useful signal that the assumption needs investigation.',null,'The decomposition must reconstruct every original job without inventing combinations or losing rows.',[ex('Observe one repeated asset fact','Group by the determinant and count distinct current-site values.',normalSetup,`SELECT asset_id,COUNT(DISTINCT site) AS site_values\nFROM flat_jobs GROUP BY asset_id ORDER BY asset_id;`,output([['P7',1],['P8',1]]),'This sample does not contradict the dependency. We still need the business rule that site means current site.')]),p('Understand the anomalies the split removes','An update anomaly occurs when repeated copies disagree. An insertion anomaly occurs when an asset cannot be recorded without inventing a job to hold it. A deletion anomaly occurs when removing its final job also removes the only record of the asset.\n\nSeparate asset and job tables address those problems in this example. The asset can exist before its first job and after its last one. Its current model and site have one maintained location.',null,'The benefit is clearer ownership of facts, not a ritual of splitting every column into a table.'),p('Use normal forms to examine dependencies','First normal form asks for a relation with values in the chosen domains rather than repeating groups of job columns. With a composite key, second normal form addresses non-key facts depending on only part of that key. Third normal form also addresses inappropriate transitive dependencies; its formal condition allows a dependency when its determinant is a superkey or its dependent attribute is prime. Boyce-Codd normal form requires every nontrivial determinant to be a superkey.\n\nFor our job table, asset_id is not the job key, yet it determines current site. Moving site into assets removes that dependency from jobs. Complex schemas need candidate keys and all relevant dependencies before a normal-form claim is justified.',null,'Do not infer a normal form merely by counting tables or noticing an integer primary key.'),p('Can the separated tables reconstruct the same facts?','Imagine splitting a job into one table containing job_id and asset_id, and another containing job_id and minutes. If job_id is unique in both, joining on it can reconstruct the original job. If we instead join tables using a repeated status such as open, unrelated jobs can combine and invent records. This is why a decomposition needs a lossless join, not merely fewer repeated words.\n\nFor our assets/jobs split, the shared asset_id identifies one asset row. Each job therefore finds exactly its own asset facts, provided the foreign key is enforced. Also ask whether the original dependencies can still be checked in the new tables. A decomposition that requires a large join to enforce a common write rule may introduce a practical cost even if it removes redundancy.',null,'Reconstructing the current sample is a useful test. Keys and dependencies explain why reconstruction remains correct for future permitted records.'),p('Denormalise for a measured purpose','An analytical feature table can deliberately repeat asset information to avoid repeated joins or to freeze a training snapshot. Document who builds that table, when it refreshes, and which source/version it represents.\n\nA derived snapshot should not become another independently edited source of truth. Materialised views, caches and warehouse tables need refresh and reconciliation rules. The cost of repetition is acceptable when its maintenance and temporal meaning are explicit.',null,'The later feature and incremental lessons connect this design decision to reproducible model data.')],checkpoint:[q('site means current asset location. J1 records P7 at north and J2 records P7 at south.','Which dependency is contradicted by these rows?',['asset_id determines current site','job_id determines its own row','minutes determines every asset'],0,'The same asset identifier has two dependent site values.'),tf('Two historical visits occurred before and after an asset move, and each records site at visit time.','Different site values necessarily indicate a normalisation error.',false,'They can be different correct event-time facts. The column’s temporal meaning matters.')],quiz:[q('An asset must be recorded before any inspection job exists.','What does a separate assets table permit?',['Insert the asset without inventing a job','Only store it after the first job','Remove all asset constraints'],0,'The asset and job are different entities with independent lifetimes.'),tf('A training snapshot repeats asset metadata and records its source version and build time.','This deliberate derived repetition can be appropriate.',true,'Derived copies can serve analysis if their origin and refresh policy are controlled.')],practice:[exercise('Can we split the register without losing a job?',['Create assets(id, model, site) and jobs(id, asset_id, minutes), with non-null primary keys and a foreign key from jobs.asset_id to assets.id. Copy all consistent rows from flat_jobs. Finish by joining the two tables to return job ID, asset ID, model, site and minutes ordered by job ID. The input guarantees one model/site per asset.'],normalSetup,'-- Separate asset facts from job facts.\n',normalSolution,output([['J1','P7','M2','north',20],['J2','P7','M2','north',30],['J3','P8','M3','south',15]]),['DISTINCT identifies repeated equal asset facts. It cannot repair unequal facts.','Use the asset key in jobs, then join to reconstruct the display.'],[['Reconstruct the original jobs',resultTest([['J1','P7','M2','north',20],['J2','P7','M2','north',30],['J3','P8','M3','south',15]])],['One maintained asset row','assert db.execute("SELECT COUNT(*) FROM assets WHERE id=\'P7\'").fetchone()[0] == 1'],['An asset can exist without a job','db.execute("INSERT INTO assets VALUES(\'P9\',\'M4\',\'west\')")\nassert db.execute("SELECT COUNT(*) FROM jobs WHERE asset_id=\'P9\'").fetchone()[0] == 0'],['Another job retains its identity',variant("INSERT INTO flat_jobs VALUES('J4','P7','M2','north',5);",[['J1','P7','M2','north',20],['J2','P7','M2','north',30],['J3','P8','M3','south',15],['J4','P7','M2','north',5]])]])],build:build('Find conflicting current-site copies','Repeated job records disagree about where an asset currently lives.','Group site values by the asset field, require one distinct value per asset, and return the failing IDs.',{rows:'Repeated job facts',key:'Determinant field',value:'Dependent field'},[sample('P7 has two current-site values',{rows:[{asset:'P7',site:'north'},{asset:'P7',site:'south'},{asset:'P8',site:'south'}],key:'asset',value:'site'},['P7']),sample('The repeated copies agree',{rows:[{asset:'P7',site:'north'},{asset:'P7',site:'north'}],key:'asset',value:'site'},[]),sample('Another asset now conflicts',{rows:[{asset:'P8',site:'east'},{asset:'P8',site:'west'}],key:'asset',value:'site'},['P8'])],op('ssFailedIds',op('ssOneValue',op('ssDependencyGroups',s('rows'),s('key'),s('value')))),'Distinct dependent values expose disagreement under the stated current-site meaning.','Agreement in a finite sample does not prove a functional dependency for all future records.',['Group by the determinant before judging the number of dependent values.'])});

const dmlSetup=`CREATE TABLE jobs(id TEXT PRIMARY KEY NOT NULL,status TEXT NOT NULL,minutes INTEGER NOT NULL,revision INTEGER NOT NULL);\nINSERT INTO jobs VALUES('J1','open',20,1),('J2','cancelled',0,1),('J3','done',15,3);\nCREATE TABLE incoming(id TEXT,status TEXT,minutes INTEGER,revision INTEGER);\nINSERT INTO incoming VALUES('J1','done',25,2),('J3','open',10,2),('J4','open',12,1);`;
const dmlSolution=`INSERT INTO jobs(id,status,minutes,revision)\nSELECT id,status,minutes,revision FROM incoming WHERE true\nON CONFLICT(id) DO UPDATE SET status=excluded.status,minutes=excluded.minutes,revision=excluded.revision\nWHERE excluded.revision > jobs.revision;\nDELETE FROM jobs WHERE status='cancelled' AND minutes=0;\nSELECT id,status,minutes,revision FROM jobs ORDER BY id;`;
const dml=sqlLesson({id:'sql-insert-update-delete',title:'Change the Requested Jobs Without Rewriting the Rest',topic:'Changing Shared Data',blurb:'New inspections arrive, existing ones change, and cancelled drafts leave the queue. Give each write a precise target and preserve newer information.',openingTitle:'One Status Change Updated the Entire Queue',opening:['Botie was asked to close J1. An UPDATE without a WHERE condition closed every job. The SQL was valid, but its target set was wrong.','Writing data requires the same care about row selection as reading it, with a more consequential result. We will add new jobs, accept newer revisions, and delete only the cancelled empty drafts specified by the policy.'],prerequisites:[before('Constraints','sql-constraints'),before('Filtering rows','sql-where')],history:history('Describing a Set of Rows to Change',[S('Chamberlin and Boyce: SEQUEL, 1974','https://research.ibm.com/publications/sequel-a-struciured-english-query-language'),sqlite('SQLite UPSERT','lang_upsert'),sqlite('SQLite conflict behaviour','lang_conflict')],'The early SEQUEL work described composable operations over tabular data. That set-oriented approach also means an update can target many records at once. The useful question becomes which rows satisfy the write’s predicate.','Modern dialects add ways to handle duplicate identities during insertion. SQLite’s UPSERT follows PostgreSQL-style ON CONFLICT syntax, with its own details. Our revision rule is an application policy layered on that mechanism; the database does not know which imported status is newer unless we specify it.'),reading:reading('Does the update preserve unselected jobs?','Select the intended records, replace their fields, then merge them back by identity.','A write is a selection followed by an effect','Practice. Merge newer job revisions','Updated job records'),intuition:[flow('Keep selection visible before applying a change','Closing the chosen job should not alter the other records.',[['Original queue','J1 open; J2 open; J3 done'],['Selector','id equals J1'],['Patch','status becomes done'],['Merge by ID','J1 done; J2 open; J3 done']], 'Previewing a selector helps inspection; a live transaction still needs protection against concurrent changes.')],technicalPart:3,checkpointAfter:2,parts:[p('Inspect the set you intend to change','Start with a SELECT using the same intended predicate. Include the primary key and fields that will change. Check whether zero, one or several rows would be expected.\n\nA preview is useful evidence, but another writer can change data after the preview. Keep critical preconditions in the actual UPDATE or DELETE, and use transactions or version checks when the operation depends on previously read state.',null,'A WHERE condition is part of the business operation, not optional punctuation.'),p('Insert with an explicit field mapping','INSERT INTO jobs(id,status,minutes,revision) names the destination fields. VALUES adds literal records; INSERT ... SELECT copies records calculated from another table. Constraints apply to the resulting rows in both cases.\n\nAn omitted field may receive a default. Explicit NULL has a different meaning from asking for that default. Avoid inserting a full row positionally when schema changes could reorder the fields.',null,'The incoming table is a staging area. Its rows are proposals until the application’s conflict policy accepts them.'),p('Update selected rows from their current values','UPDATE jobs SET minutes = minutes + 5 WHERE id = ... expresses an increment relative to the stored value. Fetching a value into the application, adding there, then writing the result can lose a concurrent update.\n\nFor status changes, include the expected state when the transition requires one. Check affected-row counts in the application and treat an unexpected zero as a conflict or missing record, rather than announcing success.',null,'The concurrency lesson will make an expected version part of the predicate.',[ex('Close one selected job','The predicate leaves other jobs alone.',dmlSetup,`UPDATE jobs SET status='done' WHERE id='J1' AND status='open';\nSELECT id,status FROM jobs ORDER BY id;`,output([['J1','done'],['J2','cancelled'],['J3','done']]),'The displayed IDs make the target set visible.')]),p('Handle repeated identities with an explicit policy','UPSERT handles a uniqueness conflict during insertion. excluded names the proposed row in SQLite’s DO UPDATE clause. Our rule accepts it only if its revision is greater than the stored revision. An older arrival therefore cannot overwrite a newer status.\n\nSQLite INSERT ... SELECT may need a WHERE clause before ON CONFLICT to disambiguate its parser; WHERE true is sufficient when no source filtering is needed. An equal revision with different content is a source-contract error to quarantine, not a reason to pick whichever arrival happened last.',null,'ON CONFLICT handles uniqueness conflicts. It does not excuse violated foreign keys or CHECK constraints.'),p('A replacement is not always an update','SQLite INSERT OR REPLACE can delete a conflicting row before inserting a replacement. That can interact with references and other database behaviour differently from updating selected fields. Use a deliberate UPSERT when the intended operation is an update.\n\nOur delete policy removes only cancelled jobs with zero minutes. A completed inspection is historical data and remains. Hard deletion, soft deletion and retention rules need to match the records’ purpose.',null,'Never use a convenient conflict keyword without checking which effect it actually performs.'),p('Make repeated delivery predictable','A source can replay the same batch after a failure. A stable primary key and revision comparison make our merge leave the same final rows on a replay. Repeating an unconditional increment would instead add the value again.\n\nIdempotency belongs to the operation’s semantics. It is not a property of every SQL statement. Use operation identities for repeated business effects and keep the transaction boundary aligned with what the application reports as committed.',null,'The last lesson will combine this merge with a durable ingestion checkpoint.'),p('Review write results before reporting success','RETURNING can expose changed rows in supported dialects, including the SQLite version used here. An application can also inspect affected-row counts and query the committed result. Choose the method that fits the driver and transaction policy.\n\nKeep errors visible. Do not catch every constraint failure and announce that the batch succeeded. If a batch deliberately quarantines rejected rows, record which ones failed and why so the import can be reconciled.',null,'The challenge’s final SELECT is a visible result. Its tests also replay data and add records the original example did not contain.')],checkpoint:[q('UPDATE jobs SET status=\'done\' is executed with no WHERE clause.','Which rows are targeted?',['Every row in jobs','Only the first row','Only rows currently open'],0,'The statement contains no row restriction.'),tf('An incoming revision is 2 while the stored revision is 3. The declared policy accepts only greater revisions.','The stored row should remain unchanged.',true,'Arrival order does not override the version policy.')],quiz:[q('The same batch is delivered twice. Its stable IDs and revisions are unchanged.','Which merge rule avoids applying the same revision again?',['Update only where incoming revision is greater','Increment every stored duration on every arrival','Delete every row before each insert'],0,'The newer-version predicate makes replayed records no-ops under the stated source contract.'),tf('SQLite INSERT OR REPLACE is used for a row referenced elsewhere.','It is always equivalent to updating a few selected fields.',false,'Replacement can delete the conflicting row before insertion, so its effects differ.')],practice:[exercise('Can a delayed import preserve the newer job?', ['Merge incoming into jobs by id. Insert new IDs and update status, minutes and revision only when the incoming revision is greater. Remove jobs only when status is cancelled and minutes is zero. Finish with id,status,minutes,revision ordered by id. Inputs guarantee equal revisions have equal payloads.'],dmlSetup,'-- Merge by id and revision, then remove cancelled empty drafts.\n',dmlSolution,output([['J1','done',25,2],['J3','done',15,3],['J4','open',12,1]]),['excluded refers to the proposed row in an UPSERT.','Include WHERE true on INSERT ... SELECT before ON CONFLICT when needed by SQLite’s parser.'],[['Initial merge',resultTest([['J1','done',25,2],['J3','done',15,3],['J4','open',12,1]])],['Replay stays unchanged','assert query_rows(sql, setup_sql + sql) == rows'],['A cancelled job with actual work remains',variant("INSERT INTO jobs VALUES('J5','cancelled',8,1);",[['J1','done',25,2],['J3','done',15,3],['J4','open',12,1],['J5','cancelled',8,1]])],['A newer record replaces the stored revision',variant("UPDATE incoming SET revision=4,minutes=40 WHERE id='J3';",[['J1','done',25,2],['J3','open',40,4],['J4','open',12,1]])]])],build:build('Close one job without changing its neighbours','A status update belongs to one selected job.','Match the selector, patch its selected fields and merge the result into the original rows.',{rows:'Current queue',selector:'Write predicate',patch:'Replacement values'},[sample('Close J1',{rows:[{id:'J1',status:'open'},{id:'J2',status:'open'}],selector:{id:'J1'},patch:{status:'done'}},[{id:'J1',status:'done'},{id:'J2',status:'open'}]),sample('The requested ID is absent',{rows:[{id:'J1',status:'open'},{id:'J2',status:'open'}],selector:{id:'J9'},patch:{status:'done'}},[{id:'J1',status:'open'},{id:'J2',status:'open'}]),sample('Require the old state too',{rows:[{id:'J1',status:'cancelled'}],selector:{id:'J1',status:'open'},patch:{status:'done'}},[{id:'J1',status:'cancelled'}])],op('ssMergeRows',s('rows'),op('ssPatchRows',op('ssMatchRows',s('rows'),s('selector')),s('patch'))),'The original rows stay present while the selected records receive their field changes.','This is a record transformation. Atomicity and concurrent database writes require the SQL mechanisms in the next lessons.',['A selected record needs both its ID and the new fields before it can be merged back.'])});

const transferSetup=`CREATE TABLE stock(id TEXT PRIMARY KEY NOT NULL,units INTEGER NOT NULL CHECK(units>=0));\nINSERT INTO stock VALUES('north',10),('south',2);\nCREATE TABLE request(id TEXT,source TEXT,destination TEXT,amount INTEGER); INSERT INTO request VALUES('T1','north','south',3);\nCREATE TABLE transfers(id TEXT PRIMARY KEY NOT NULL,source TEXT NOT NULL,destination TEXT NOT NULL,amount INTEGER NOT NULL);`;
const transferSolution=`BEGIN;\nINSERT INTO transfers(id,source,destination,amount)\nSELECT r.id,r.source,r.destination,r.amount FROM request r\nJOIN stock a ON a.id=r.source JOIN stock b ON b.id=r.destination\nWHERE r.amount>0 AND r.source<>r.destination AND a.units>=r.amount;\nUPDATE stock SET units=units-COALESCE((SELECT amount FROM transfers WHERE source=stock.id),0)\n+COALESCE((SELECT amount FROM transfers WHERE destination=stock.id),0);\nCOMMIT;\nSELECT id,units FROM stock ORDER BY id;`;
const staged=op('ssApplyDeltas',s('stock'),s('deltas'));
const transactions=sqlLesson({id:'sql-transactions',title:'Move Spare Parts Without Losing Half the Transfer',topic:'Changing Shared Data',blurb:'A transfer changes two stock balances and its audit record. Make those changes one unit of work, and learn what a rollback can actually undo.',openingTitle:'The Parts Left the North Store but Never Reached the South Store',opening:['Botie subtracts three replacement seals from the north store. The next statement fails before the south store is updated. The database now describes missing stock even though the intended transfer was one operation.','A transaction gives these related changes a boundary. We can publish them together or abandon the database changes together. We will also use a savepoint to undo an optional part of a larger operation.'],prerequisites:[before('Changing records','sql-insert-update-delete')],history:history('Making a Business Operation Survive a Failure',[S('Jim Gray: The Transaction Concept, 1981','https://www.cs.utexas.edu/~dahlin/Classes/GradOS/papers/Gray81.pdf'),sqlite('SQLite transactions','lang_transaction'),sqlite('SQLite savepoints','lang_savepoint')],'Transaction-processing research addressed operations whose meaning spanned several low-level writes. Jim Gray’s 1981 paper described the transaction concept and its limitations. The problem was practical: interruptions should not leave half of an intended database operation visible as a completed result.','Our spare-parts transfer is an invented example of that boundary. It updates database records only. Sending a delivery truck or an email involves another system whose effects are not automatically reversed by a SQL rollback.'),reading:reading('Would the complete transfer leave valid balances?','Stage both changes, check the resulting balances, then select all staged rows or all original rows.','Treat the related database changes as one decision','Practice. Commit a valid stock transfer','Committed stock records'),intuition:[table('The intended operation changes both stores','A transfer should preserve the total stock in this example.',['State','North store','South store'],[['Before','10','2'],['After subtraction only','7','2'],['After the whole transfer','7','5']],'The middle row is an incomplete business operation, even though each written value is a valid integer.')],technicalPart:3,checkpointAfter:2,parts:[p('Choose the transaction’s business boundary','The transfer consists of validating the request, recording it, subtracting source stock and adding destination stock. Committing only the subtraction would report a result the business never intended.\n\nKeep the boundary as small as possible while preserving that invariant. Long transactions can hold resources and delay other writers. Avoid waiting for a person or an unrelated network call while a transaction is open.',null,'A transaction boundary follows the operation’s meaning, not an arbitrary number of statements.'),p('Separate atomicity from the rest of correctness','Atomicity concerns all-or-nothing database effects. Consistency means the transaction should preserve declared invariants; the application must still express those rules correctly. Isolation governs interaction with other transactions. Durability concerns retaining committed changes under the database’s documented configuration and failure assumptions.\n\nA transaction containing an incorrect unrestricted UPDATE can commit perfectly and still damage every row. Transactions do not discover the intended predicate or business policy.',null,'We will study isolation separately because concurrent work creates failures that a single-session example cannot display.'),p('Use BEGIN, COMMIT and ROLLBACK deliberately','BEGIN starts the explicit unit. COMMIT publishes its successful database changes. ROLLBACK abandons its uncommitted changes. The SQL worksheet does not automatically commit between your statements, so these boundaries can be exercised directly.\n\nDriver defaults matter outside the worksheet. Python sqlite3 versions and connection settings affect implicit transactions, and executescript has special transaction behaviour. Read the driver contract and keep application exception handling responsible for rolling back a failed unit.',null,'A failed statement does not necessarily roll back every earlier statement in the transaction. Check the engine and conflict policy.'),p('Mark an optional part with a savepoint','A savepoint names a position within the current work. ROLLBACK TO returns to that position while keeping the savepoint active; RELEASE removes the savepoint boundary. Releasing an inner savepoint is not the same as durably committing the outer transaction.\n\nThis is useful when an optional batch item may be abandoned while the application deliberately keeps earlier valid work. It should not hide a failure that invalidates the whole business operation.',null,'Nested BEGIN transactions are not how SQLite provides this behaviour.',[ex('Undo a tentative stock adjustment','Only the edit after the savepoint is abandoned.',transferSetup,`BEGIN;\nUPDATE stock SET units=units+1 WHERE id='north';\nSAVEPOINT optional_count;\nUPDATE stock SET units=0 WHERE id='south';\nROLLBACK TO optional_count;\nRELEASE optional_count;\nCOMMIT;\nSELECT id,units FROM stock ORDER BY id;`,output([['north',11],['south',2]]),'The north adjustment preceded the savepoint. The tentative south value did not survive rollback to it.')]),p('Keep validation and its writes in the same unit','The challenge has exactly one proposed transfer and an initially empty transfers table. It first inserts an audit row only if both stores exist, the amount is positive, the stores differ and the source has enough stock. Both stock updates then follow that accepted row.\n\nA live multi-writer implementation also needs a concurrency strategy. For SQLite a deliberately acquired write transaction may be appropriate; PostgreSQL can use row locks or carefully designed conditional updates. A read performed outside the write transaction is not a reservation of stock.',null,'The browser fixture demonstrates a transaction’s logical effects, not simultaneous users or crash recovery.'),p('A rollback has a boundary too','A database rollback cannot unsend a message already accepted by another service. If a committed transfer must trigger an external message, an outbox record written in the same database transaction can support reliable later delivery. The delivery process still needs deduplication and recovery.\n\nA cancellation after commit requires a new compensating business operation when reversal is allowed. Preserve the audit trail instead of claiming the original transfer never occurred.',null,'Treat a commit result that was lost over a connection as an uncertain outcome to reconcile, rather than blindly repeating a consequential operation.')],checkpoint:[q('The source deduction committed. The destination addition failed in a later transaction.','What boundary was missing?',['One transaction covering the related database changes','A shorter column name','An ORDER BY on the stock table'],0,'The business transfer spans both balances.'),tf('A transaction executes an incorrect UPDATE that changes every job, then commits successfully.','Atomicity alone makes the operation correct.',false,'Atomicity preserves its unit of work; it does not validate the intended target set.')],quiz:[q('An outer transaction contains SAVEPOINT extra, an optional write, ROLLBACK TO extra, and RELEASE extra.','What does RELEASE establish here?',['The savepoint is removed; the outer transaction still controls commit','Every earlier database write is durably committed','The entire outer transaction was rolled back'],0,'Releasing an inner savepoint does not commit the outer transaction.'),tf('A database transaction is rolled back before commit and its only effects were database writes.','Its uncommitted database changes should not become a successful partial transfer.',true,'That is the intended atomic boundary, subject to the database’s guarantees.')],practice:[exercise('Can both stores agree on one accepted transfer?',['The setup has one request and an empty transfers table. Within one explicit transaction, record the transfer only when amount is positive, source differs from destination, both stores exist and the source has enough units. Apply both stock changes only for that accepted transfer. Commit, then return stock id and units ordered by id. An invalid request must leave both stock and transfers unchanged.'],transferSetup,'-- Validate and record the transfer, then update both balances in one transaction.\n',transferSolution,output([['north',7],['south',5]]),['An accepted audit row can drive both updates inside the transaction.','If no row is accepted, each balance change should be zero.'],[['Both balances change',resultTest([['north',7],['south',5]])],['One audit record and no open transaction','assert db.execute("SELECT COUNT(*) FROM transfers").fetchone()[0] == 1\nassert not db.in_transaction'],['Insufficient stock leaves the original balances',variant("UPDATE request SET amount=11;",[['north',10],['south',2]])],['Missing destination is rejected',variant("UPDATE request SET destination='absent';",[['north',10],['south',2]])],['Different valid amount',variant("UPDATE request SET amount=2;",[['north',8],['south',4]])]])],build:build('Publish both sides of a stock transfer','A proposed transfer can leave a negative source balance.','Stage the changes, validate every resulting balance, then choose the whole staged state or the whole original state.',{stock:'Current store balances',deltas:'Proposed changes by store'},[sample('Transfer three seals',{stock:[{id:'north',units:10},{id:'south',units:2}],deltas:{north:-3,south:3}},[{id:'north',units:7},{id:'south',units:5}]),sample('The source cannot supply twelve',{stock:[{id:'north',units:10},{id:'south',units:2}],deltas:{north:-12,south:12}},[{id:'north',units:10},{id:'south',units:2}]),sample('A reverse transfer is possible',{stock:[{id:'north',units:10},{id:'south',units:2}],deltas:{north:2,south:-2}},[{id:'north',units:12},{id:'south',units:0}])],op('ssCommitChoice',op('ssNonnegative',staged),staged,s('stock')),'Validation applies to the complete staged state, so rejection restores both original balances.','This is an atomic-choice teaching model. It does not simulate disk persistence, locks or the database transaction log.',['Inspect staged balances before choosing the state to publish.'])});

const concurrentSetup=`CREATE TABLE jobs(id TEXT PRIMARY KEY NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL);\nINSERT INTO jobs VALUES('J1','assigned',4),('J2','open',1);\nCREATE TABLE edit(id TEXT,expected_version INTEGER,status TEXT); INSERT INTO edit VALUES('J1',4,'done');`;
const concurrentSolution=`UPDATE jobs SET status=(SELECT status FROM edit),version=version+1\nWHERE id=(SELECT id FROM edit) AND version=(SELECT expected_version FROM edit);\nSELECT id,status,version FROM jobs ORDER BY id;`;
const concurrency=sqlLesson({id:'sql-concurrency',title:'What If Someone Changes the Job While Botie Is Reading It?',topic:'Changing Shared Data',blurb:'Two valid edits can overwrite each other. Make stale assumptions visible, and distinguish version checks from the database’s isolation guarantees.',openingTitle:'The Second Save Quietly Erased the First Edit',opening:['Two technicians read J1 at version 4. One assigns a replacement specialist and saves version 5. The other closes the earlier copy, unaware that the job changed. A blind save can overwrite work that happened after the read.','We will first use an expected version to reject a stale edit. Then we will examine what snapshots, write locks and isolation levels can guarantee in a real database.'],prerequisites:[before('Transactions','sql-transactions')],history:history('Coordinating Readers and Writers Without Losing Work',[sqlite('SQLite isolation','isolation'),sqlite('SQLite file locking','lockingv3'),postgres('PostgreSQL transaction isolation','transaction-iso')],'Shared databases needed to coordinate transactions whose operations overlapped. Locking and multi-version approaches provide different ways to control which state a transaction can observe and change. These mechanisms developed to support concurrent applications, long before a model could issue SQL.','SQLite and PostgreSQL expose different concurrency models. SQLite serialises writers, while WAL mode lets readers keep an earlier snapshot as a writer commits. PostgreSQL offers several isolation levels with their own anomaly and retry rules. Our one-connection exercise illustrates an optimistic version predicate, not either engine’s full scheduler.'),reading:reading('Does the edit still match the version it was based on?','Compare the proposal with the stored version before applying its replacement status.','Keep stale assumptions in the write predicate','Practice. Apply an optimistic version check','Resulting job record'),intuition:[table('Two edits began from the same record','A later save must notice that its original view is old.',['Moment','Stored version','Second editor’s expected version'],[['Both read J1','4','4'],['First edit commits','5','4'],['Second editor tries to save','5','4']], 'The version mismatch asks the second editor to reload and reconsider the change.')],technicalPart:3,checkpointAfter:2,parts:[p('A read is an observation, not a reservation','Reading a row tells the application what was visible at that moment under its transaction rules. Another transaction may commit before the application writes. A user thinking about an edit can make that gap quite long.\n\nCarry the observed version with the proposed change. The application should explain a conflict and show the current state when the version no longer matches. Automatically reapplying the old decision can be wrong even if the SQL is retried successfully.',null,'The conflict concerns the meaning of the edit, not merely a temporary database error.'),p('Put the expected version in the UPDATE','Match both the primary key and expected version in the same UPDATE predicate. If it matches, update the fields and increment the version. A stale proposal affects zero rows. The application must inspect that outcome instead of reporting a successful save.\n\nThis protects against a lost update for cooperating writers that follow the version protocol. It does not independently enforce a condition involving several different rows. Every write path that can change the relevant state must maintain the version.',null,'The version is a concurrency token. It need not be a timestamp, and clock ordering is unnecessary for this comparison.'),p('Try a successful edit and then replay the stale one','The supplied edit expects version 4. The first application of the statement can produce version 5. Replaying the same proposal must leave version 5 untouched because the expectation is still 4.\n\nAn application that wants another edit obtains the new record and creates a new deliberate proposal. It should not silently replace expected_version with whatever is current just to make the UPDATE succeed.',null,'The exercise has one edit row. The key and version predicate generalise when the driver binds a different proposal.',[ex('A stale editor cannot close the changed job','Change the stored version first, then apply the old expected version.',concurrentSetup,`UPDATE jobs SET status='review',version=5 WHERE id='J1';\nUPDATE jobs SET status='done',version=version+1 WHERE id='J1' AND version=4;\nSELECT id,status,version FROM jobs ORDER BY id;`,output([['J1','review',5],['J2','open',1]]),'The old proposal matched no row. The other job also remains untouched.')]),p('What SQLite serialises','SQLite permits only one writer at a time. Its journal mode affects reader/writer interaction: WAL readers can keep a snapshot while a writer commits. A read transaction may be unable to upgrade to a writer when its snapshot is no longer current.\n\nBEGIN IMMEDIATE requests the write transaction earlier and can fail when another writer holds it. It does not make multiple SQLite writers execute their writes simultaneously. Set bounded busy handling and keep transactions short. The in-browser worksheet uses one isolated connection, so it cannot demonstrate real lock contention.',null,'Sequentially replaying a stale edit is a controlled illustration of an application precondition, not a concurrency benchmark.'),p('What PostgreSQL isolation levels change','At PostgreSQL Read Committed, a statement reads a snapshot established for that statement, with documented rules for concurrent updates. Repeatable Read gives a transaction a stable snapshot but still permits some anomalies that Serializable prevents. Serializable execution may reject a transaction so that the application retries the complete unit.\n\nSELECT ... FOR UPDATE can lock selected rows when pessimistic coordination is appropriate. It does not automatically lock every possible future row that could satisfy an arbitrary business rule. Choose the isolation and locking strategy from the invariant, and test the exact interleaving that could break it.',null,'A generic claim that transactions prevent all races hides the isolation level that actually governs them.'),p('One row version cannot protect a rule across several rows','Suppose two engineers must never both leave the on-call rota. Each reads a snapshot showing the other still on call, then updates only their own row to off call. Both individual row versions can match even though their combined result breaks the rota rule. This is a write-skew pattern: the writes affect different rows, but both decisions relied on a shared condition.\n\nProtect the condition at the database boundary. Depending on the engine and schema, the solution can use a common row that competing decisions lock, a suitable constraint, or serializable transactions with retry handling. PostgreSQL Repeatable Read uses snapshot isolation and can permit serialization anomalies of this kind; Serializable can reject a conflicting execution instead. SQLite permits one writer at a time, but an application that reads outside its eventual write transaction can still act on stale decisions. The transaction boundary is part of the design.',null,'Our versioned job edit solves a single-row stale overwrite. It does not claim to enforce every rule involving a set of jobs.'),p('Retry the whole decision when its read assumptions changed','A serialization failure can require retrying the transaction from the beginning with fresh reads. Repeating only the final UPDATE preserves stale calculations. Keep retries bounded and make external effects replay-safe.\n\nFor an optimistic user-edit conflict, asking the user to reconcile may be preferable to automatic retry. Record the conflict and current state. Avoid a loop that continually overwrites newer work until one write finally succeeds.',null,'The next lessons improve query cost; they should preserve these correctness requirements while changing execution plans.')],checkpoint:[q('Stored J1 has version 5. The proposed update requires version 4.','How many rows should its key-and-version predicate update?',['Zero','One with version reset to 4','Every job at the site'],0,'The expected version is a required write precondition.'),tf('One write path edits a job without updating its version.','That can undermine a version-check protocol used by other writers.',true,'Those writers may no longer detect that their observed record changed.')],quiz:[q('A PostgreSQL Serializable transaction fails because its reads and writes conflict with concurrent work.','What does a correct retry generally need?',['Repeat the transaction’s decision with fresh reads','Retry only its last statement using old calculations','Disable all constraints'],0,'The invalidated assumptions may come from earlier reads in the unit.'),tf('The SQLite worksheet uses one isolated connection.','Its sequential version-check exercise proves how a live multi-user server schedules transactions.',false,'It illustrates the predicate only. Live isolation and contention require separate multi-connection tests.')],practice:[exercise('Can a stale job edit leave newer work intact?',['Use the single edit row to update jobs.status and increment jobs.version by one only when both id and expected_version match. Return id,status,version for all jobs ordered by id. Preserve every unrelated row. Replaying the same edit must not increment the version again.'],concurrentSetup,'-- Keep the expected version in the actual UPDATE predicate.\n',concurrentSolution,output([['J1','done',5],['J2','open',1]]),['The proposed ID and version must both match in WHERE.','Increment from the current stored version only for a matching row.'],[['Matching edit',resultTest([['J1','done',5],['J2','open',1]])],['Stale edit',variant("UPDATE jobs SET version=6,status='review' WHERE id='J1';",[['J1','review',6],['J2','open',1]])],['Replay does not increment again','assert query_rows(sql, setup_sql + sql) == rows'],['A different matching job',variant("UPDATE edit SET id='J2',expected_version=1,status='assigned';",[['J1','assigned',4],['J2','assigned',2]])]])],build:build('Keep a stale edit from replacing a newer job','The proposed status was chosen using an earlier job version.','Compare the proposal’s identity and expected version with the current record, then apply its patch only when that comparison passes.',{current:'Stored job',proposal:'Versioned edit'},[sample('The expected version still matches',{current:{id:'J1',status:'assigned',version:4},proposal:{id:'J1',expected_version:4,status:'done'}},{id:'J1',status:'done',version:5}),sample('Another editor committed first',{current:{id:'J1',status:'review',version:5},proposal:{id:'J1',expected_version:4,status:'done'}},{id:'J1',status:'review',version:5}),sample('The proposal names another job',{current:{id:'J2',status:'open',version:4},proposal:{id:'J1',expected_version:4,status:'done'}},{id:'J2',status:'open',version:4})],op('ssVersionedPatch',op('ssVersionMatch',s('current'),s('proposal')),s('current'),s('proposal')),'A matching version is consumed by incrementing it, so replayed old edits no longer match.','The workshop is a sequential optimistic-check model. It does not simulate locks, isolation levels or simultaneous transactions.',['The comparison needs both identity and version.'])});

const indexSolution=`CREATE INDEX readings_asset_time ON readings(asset_id,recorded_at);\nSELECT id,recorded_at,value FROM readings\nWHERE asset_id='P7' AND recorded_at>='2026-01-02' AND recorded_at<'2026-01-04'\nORDER BY recorded_at,id;`;
const indexRows=[{id:'R1',asset:'P7',day:1},{id:'R2',asset:'P8',day:2},{id:'R3',asset:'P7',day:3},{id:'R4',asset:'P8',day:4}];
const indexes=sqlLesson({id:'sql-indexes',title:'Find One Pump’s Readings Without Checking Every Pump',topic:'Making Queries Practical',blurb:'The reading table keeps growing. Arrange useful lookup keys so the database can find a small candidate region, then account for the cost of maintaining that structure.',openingTitle:'Why Read Every Sensor Record to Find P7’s Morning?',opening:['The team asks for P7’s readings within a short time range. The table also contains years of measurements from other assets. Checking every row works, but the work grows with data the question does not need.','An index keeps an additional structure organised by selected values. We will examine what its ordering makes easy, then create a composite index without changing the query’s answer.'],prerequisites:[before('Ordering results','sql-order-limit'),before('Changing records','sql-insert-update-delete')],history:history('Letting the Database Choose an Access Path',[S('Selinger and colleagues: Access path selection, 1979','https://research.ibm.com/publications/access-path-selection-in-a-relational-database-management-system'),sqlite('SQLite query planning','queryplanner'),postgres('PostgreSQL multicolumn indexes','indexes-multicolumn')],'SQL lets a caller describe desired records without specifying their physical traversal. System R’s 1979 access-path paper described choosing routes for queries, including joins. Indexes provide candidate routes that the optimiser can compare with reading a table.','Our pump-and-time example gives a physical intuition: equal leading keys occupy a region of an ordered index. The widget lays out records directly; it does not implement database pages, B-tree balancing or disk I/O.'),reading:reading('Which records occupy the selected index prefix?','Order records by the declared keys, find the leading-key region, then expose the candidate IDs.','The key order determines which region is contiguous','Practice. Add an index for an asset’s time range','Candidate reading IDs'),intuition:[table('Compare two useful orderings','Both contain the same records. Their leading key groups different questions together.',['Index order','Easy contiguous region','What still needs checking'],[['asset, time','One asset then a time range','Other predicates and returned columns'],['time, asset','One time range across assets','Filtering one asset inside that range']], 'An index is an additional access structure. It does not change the table’s logical row set.')],technicalPart:3,checkpointAfter:2,parts:[p('An index stores a route back to the records','A typical B-tree index arranges key values so a search can narrow to a relevant region rather than inspect every table row. Leaf entries connect that region to stored row identities or values, depending on the database and index structure.\n\nThe database must still retrieve or verify the requested data. If most rows match, a sequential scan can be cheaper. Small tables may also favour scanning because an index lookup adds overhead.',null,'The existence of an index does not require the optimiser to use it.'),p('Read a composite index from its leading key','For an index on asset_id, recorded_at, rows for one asset are grouped before their times are ordered. Equality on the asset and a time range can therefore narrow a contiguous region.\n\nA condition on a later column alone does not generally provide the same direct leading-prefix lookup. Some engines can use additional strategies such as skip scans, so avoid the absolute claim that later columns can never help. Inspect the chosen plan for the actual database and data.',null,'Choose the index order from recurring predicates and ordering needs, not alphabetical column names.'),p('Keep a range predicate usable by the index','A direct range on recorded_at lets an ordinary index on that column represent the bounds. Wrapping it in a function can prevent that particular access path unless an appropriate expression index or optimiser transformation applies. This property is often called sargability: whether a predicate can be used as a search argument.\n\nUse a half-open time interval with an inclusive start and exclusive end when that matches the domain. It avoids inventing the last fraction of a second in a day. Our fixture uses consistently formatted date text; mixed offsets or formats require a stronger time representation.',null,'An efficient rewrite must return the same boundary records as the original intended question.',[ex('Create the lookup order and inspect its columns','PRAGMA index_info reports the declared column sequence without depending on a planner’s output wording.',readings,`CREATE INDEX example_asset_time ON readings(asset_id,recorded_at);\nSELECT name FROM pragma_index_info('example_asset_time') ORDER BY seqno;`,output([['asset_id'],['recorded_at']]),'Asset is the leading key. The challenge will use that prefix and an explicit time range.')]),p('An index can also cover a result','If an index contains all values needed by a query, an engine may avoid some visits to the base table. Such a covering access path trades additional index size and write maintenance for less reading. The exact columns implicitly available depend on the database and table structure.\n\nDo not append every column to every index. Measure representative queries and inspect whether table lookups are a real cost. Sensitive columns in duplicated storage also remain part of the data-management responsibility.',null,'Covering is a property of an index relative to a query, not a universal property of the index name.'),p('Every write maintains the additional structure','Inserts add index entries, deletes remove them, and updates to indexed values move or replace entries. Indexes consume space and can increase write latency. Several overlapping indexes may provide little extra value while multiplying that cost.\n\nUniqueness indexes also enforce correctness and cannot be discarded merely because one read benchmark is faster without them. Review constraints and workload together before changing an index set.',null,'Read optimisation and invariant enforcement can share a structure while serving different purposes.'),p('Verify with the plan and a representative workload','Create the candidate index, confirm that answers remain correct, then inspect EXPLAIN QUERY PLAN in SQLite. Use representative row counts and value distributions when measuring. A four-row exercise is useful for syntax and semantics but cannot establish production speed.\n\nDatabase statistics help the optimiser estimate selectivity. Keep their maintenance appropriate to the engine and version, and investigate skewed values separately. The next lesson compares planned work and observed work without treating either as a promise.',null,'The challenge tests the index’s declared key order and query results. It does not demand an unstable exact plan string.')],checkpoint:[q('An index orders keys by asset_id then recorded_at. A query selects one asset and a time range.','Which key narrows the leading region?',['asset_id','The row’s display position','An unrelated status column'],0,'The leading asset key groups that asset’s time-ordered entries together.'),tf('A query matches nearly every row in a small table.','A full scan can be a reasonable plan even when an index exists.',true,'The index lookup overhead may not save enough row access.')],quiz:[q('A direct recorded_at range is replaced with a function applied to recorded_at, with no matching expression index.','What should be checked?',['Whether the intended index access remains available and results stay equivalent','Only whether the function name is shorter','Whether SQL keywords are uppercase'],0,'Both semantics and access-path usability matter.'),tf('Adding indexes improves some reads.','Additional indexes are free for inserts and updates.',false,'Writes must maintain the extra access structures.')],practice:[exercise('Can the database find P7’s bounded interval with an appropriate key order?',['Create a non-unique index on readings whose first two keys are asset_id then recorded_at. Return id, recorded_at and value for P7 from 2026-01-02 inclusive to 2026-01-04 exclusive, ordered by recorded_at then id. Do not remove records or change values.'],readings,'-- Create the index and query the half-open interval.\n',indexSolution,output([[2,'2026-01-02',24],[4,'2026-01-03',26]]),['Index key order and result ORDER BY solve related but different problems.','Use >= for the start and < for the end.'],[['Correct interval',resultTest([[2,'2026-01-02',24],[4,'2026-01-03',26]])],['Declared composite key','indexes = db.execute("PRAGMA index_list(readings)").fetchall()\nassert any([r[2] for r in db.execute("PRAGMA index_info(" + repr(i[1]) + ")")] [:2] == ["asset_id","recorded_at"] for i in indexes)'],['Boundary and unrelated records',variant("INSERT INTO readings VALUES(6,'P7','2026-01-04',30),(7,'P7','2026-01-02',22),(8,'P9','2026-01-02',50);",[[2,'2026-01-02',24],[7,'2026-01-02',22],[4,'2026-01-03',26]])],['No source records removed','assert db.execute("SELECT COUNT(*) FROM readings").fetchone()[0] == 5']])],build:build('Find the asset region in a composite ordering','The table contains measurements from several pumps.','Sort by the supplied index keys, keep the requested leading equality prefix, then return IDs in index order.',{rows:'Reading identities and key values',keys:'Ordered index columns',prefix:'Leading equality keys'},[sample('Find P7 in asset-time order',{rows:indexRows,keys:['asset','day'],prefix:{asset:'P7'}},['R1','R3']),sample('Look up P8 instead',{rows:indexRows,keys:['asset','day'],prefix:{asset:'P8'}},['R2','R4']),sample('Time is deliberately the leading key',{rows:indexRows,keys:['day','asset'],prefix:{day:3}},['R3'])],op('ssIds',op('ssPrefixCandidates',op('ssSortRecords',s('rows'),s('keys')),s('keys'),s('prefix'))),'A leading equality prefix identifies a candidate region in the chosen lexicographic ordering.','This record ordering illustrates index geometry. It does not model B-tree cost, optimiser choices or real I/O.',['Keep the index-key list connected to both ordering and prefix selection.'])});

const plansSetup=`CREATE TABLE assets(id TEXT PRIMARY KEY NOT NULL); INSERT INTO assets VALUES('P7'),('P8'),('P9');\nCREATE TABLE visits(id INTEGER PRIMARY KEY,asset_id TEXT NOT NULL,minutes INTEGER NOT NULL); INSERT INTO visits VALUES(1,'P7',20),(2,'P7',30),(3,'P8',10);`;
const plansSolution=`WITH totals AS (SELECT asset_id,COUNT(*) AS visits,SUM(minutes) AS minutes FROM visits GROUP BY asset_id)\nSELECT a.id,COALESCE(t.visits,0),COALESCE(t.minutes,0)\nFROM assets a LEFT JOIN totals t ON t.asset_id=a.id ORDER BY a.id;`;
const plans=sqlLesson({id:'sql-query-plans',title:'Why Does a Short Query Repeat So Much Work?',topic:'Making Queries Practical',blurb:'A compact query can scan the same table repeatedly. Read the access plan, preserve the answer, and compare work on data that resembles the real job.',openingTitle:'Botie Counts the Entire Visit Table Again for Each Pump',opening:['The report needs visit counts and minutes for every asset. A convenient query asks two correlated subqueries for every asset. With a small register that looks harmless; a growing visit history can make the repeated work expensive.','We will group the visit data once at the required grain and join it to the register. The larger lesson is how to inspect a plan and test a rewrite without confusing a shorter SQL statement with a faster or correct one.'],prerequisites:[before('Indexes','sql-indexes'),before('Common table expressions','sql-ctes'),before('Left joins','sql-left-joins')],history:history('Choosing Work from a Declarative Request',[S('System R access-path selection, 1979','https://research.ibm.com/publications/access-path-selection-in-a-relational-database-management-system'),sqlite('SQLite EXPLAIN QUERY PLAN','eqp'),postgres('PostgreSQL EXPLAIN','sql-explain'),sqlite('SQLite ANALYZE','lang_analyze')],'The System R work showed how a database could choose access paths for a declarative request instead of requiring the caller to prescribe every step. That freedom creates several possible plans for the same logical result. Estimating their costs depends on what the engine knows about the data.','EXPLAIN facilities make some of those choices visible. Their formats and meanings are engine-specific, and SQLite warns that its query-plan output can change. We will inspect plan structure without treating exact display text as an application API.'),reading:reading('Which measured plan did less comparable work?','Check answer identities before counting repeated scan visits, then choose the smaller measured count.','A faster wrong answer is still the wrong report','Practice. Aggregate visits before joining the register','Selected measured plan'),intuition:[table('Repeated work can hide behind a small node','The numbers are invented scan measurements.',['Plan','Rows examined per loop','Loops','Total row visits'],[['Repeated visit scan','100','20','2000'],['Aggregate once','100','1','100']], 'Counted row visits are one diagnostic measure. CPU, I/O, memory and elapsed time can still differ.')],technicalPart:3,checkpointAfter:2,parts:[p('Read the plan as operations on rows','A plan describes operations such as scanning a table, searching an index, joining inputs and sorting results. Follow where rows come from and how often an operation is repeated. A nested operation can be cheap once and expensive when executed for every outer row.\n\nSQLite’s EXPLAIN QUERY PLAN gives a high-level tree. Its SCAN and SEARCH descriptions help distinguish broad traversal from a constrained lookup, but interpretation depends on the chosen access path. An index scan can still visit many entries.',null,'The query text describes the result; the plan describes a route the engine currently chooses.'),p('Verify the answer before measuring speed','Our report includes assets with zero visits. An inner join would discard them and may look faster because it returns less information. A rewritten aggregate must preserve both the row grain and the intended treatment of missing matches.\n\nWrite result tests for empty visit groups, additional assets and repeated visits. Check tie ordering only where the report requires it. Comparing a fast wrong query with a correct one is not a useful optimisation result.',null,'The workshop refuses a measured plan whose answer IDs differ before comparing its scan counts.'),p('Pre-aggregate at the join grain','Group visits by asset_id so the derived table has one row per asset. Join that table to the asset register with LEFT JOIN, then replace missing count and minute totals with zero under this report’s policy.\n\nA CTE names the intermediate result so its grain is easy to see. It does not universally force materialisation or guarantee that the engine scans the source only once. Optimisers can inline or transform it. Inspect the actual chosen plan rather than inferring execution from the presence of WITH.',null,'An appropriate index can also help a correlated query. Evaluate alternatives instead of declaring one syntactic form universally best.',[ex('Inspect the aggregate before adding assets with no visits','The intermediate result has one row per asset that appears in visits.',plansSetup,`SELECT asset_id,COUNT(*) AS visits,SUM(minutes) AS minutes\nFROM visits GROUP BY asset_id ORDER BY asset_id;`,output([['P7',2,50],['P8',1,10]]),'P9 is absent here because it has no visit. The outer register join must restore its report row.')]),p('Distinguish estimates from observed execution','An optimiser estimates row counts and costs before running the query. Statistics, parameter values and correlated columns can make those estimates inaccurate. A large estimate error near the beginning of a plan can lead to poor downstream choices.\n\nPostgreSQL EXPLAIN ANALYZE actually executes the statement and reports observations such as actual rows and loops. For a write statement, it can therefore perform writes. Use a deliberate transaction and rollback where appropriate, remembering external effects may not be reversible. SQLite EXPLAIN QUERY PLAN does not provide the same runtime analysis.',null,'Do not copy an ANALYZE command into a production write path as if it were a harmless formatter.'),p('Measure representative conditions','Timing one warm-cache query on a tiny database tells us little about a larger workload. Compare realistic distributions, common and rare parameter values, repeated runs, and the resource pressure the service normally sees. Preserve result checks alongside timing.\n\nRefresh or inspect database statistics when estimates look implausible. Also check temporary sorting, spilling and repeated lookups. The workshop’s row-visits metric isolates one concept; it is not an optimiser cost model or a substitute for elapsed-time and resource measurements.',null,'A smaller measured row count is evidence about that run, not a universal speed guarantee.'),p('Keep a plan improvement explainable','Record the query version, schema/index changes, data scale and measurements used to justify an optimisation. Verify that write costs and other important queries did not regress. A new index or materialised result can move work elsewhere rather than remove it.\n\nPlans can change after a database upgrade or a data-distribution shift. Monitor the user-visible outcome and investigate plan changes when they matter. Tests should protect query semantics and deliberate schema contracts rather than exact unstable plan text.',null,'The challenge accepts any equivalent report query. To inspect your route, prefix the final SELECT (including its WITH clause, if present) with EXPLAIN QUERY PLAN and choose Run code. Remove that prefix before Run tests so the challenge receives report rows rather than plan rows.')],checkpoint:[q('A query rewrite changes a LEFT JOIN to INNER JOIN and removes assets with zero visits. The report must include all assets.','What must be fixed before comparing speed?',['The missing report rows','The query’s indentation','The index name'],0,'The rewrite no longer answers the required question.'),tf('A plan node examines 100 rows per loop and runs 20 times.','Its repeated work matters even if one loop looks small.',true,'A small inner operation can accumulate substantial work through repetition.')],quiz:[q('PostgreSQL EXPLAIN ANALYZE is applied to an UPDATE statement.','What must the operator remember?',['It executes the statement','It can never write data','It is the same as SQLite EXPLAIN QUERY PLAN'],0,'Runtime analysis requires execution, including the effects of a write statement.'),tf('A CTE names an aggregate in the SQL text.','Its presence alone guarantees one physical scan on every database.',false,'Materialisation and transformations depend on the engine, query and version.')],practice:[exercise('Can the visit report keep every asset after aggregation?',['Return one row per asset: id, visit count, total minutes. Include assets with no visits as zero and order by asset id. Use the supplied assets and visits tables; preserve them. Try grouping visits before the LEFT JOIN, then inspect the query plan. Equivalent correct SQL is accepted without requiring one exact plan string.'],plansSetup,'-- Aggregate visits at asset grain, then keep the complete asset register.\n',plansSolution,output([['P7',2,50],['P8',1,10],['P9',0,0]]),['A grouped visit table has no row for an asset with zero visits. Start the outer join from assets.','COALESCE makes the report’s zero policy explicit after the join.'],[['Complete report',resultTest([['P7',2,50],['P8',1,10],['P9',0,0]])],['Another repeated visit',variant("INSERT INTO visits VALUES(4,'P7',5);",[['P7',3,55],['P8',1,10],['P9',0,0]])],['An entirely empty history',variant('DELETE FROM visits;',[['P7',0,0],['P8',0,0],['P9',0,0]])],['Another asset without a visit',variant("INSERT INTO assets VALUES('P6');",[['P6',0,0],['P7',2,50],['P8',1,10],['P9',0,0]])]])],build:build('Compare measured work only for matching answers','Two candidate plans have measured scan counts, but one may have changed the answer.','Keep only plans whose answer IDs match the required report, calculate repeated scan visits, and choose the smallest measured count.',{plans:'Measured plan records',expected:'Required answer identities'},[sample('Grouping avoids repeated scans',{plans:[{id:'repeat',answers:['P7','P8'],scans:[{rows_per_loop:100,loops:20}]},{id:'group',answers:['P7','P8'],scans:[{rows_per_loop:100,loops:1}]}],expected:['P7','P8']},'group'),sample('The cheap plan lost an asset',{plans:[{id:'repeat',answers:['P7','P8'],scans:[{rows_per_loop:100,loops:20}]},{id:'group',answers:['P7'],scans:[{rows_per_loop:10,loops:1}]}],expected:['P7','P8']},'repeat'),sample('No plan returns the required report',{plans:[{id:'wrong',answers:['P7'],scans:[{rows_per_loop:1,loops:1}]}],expected:['P7','P8']},'no comparable plan')],op('ssLeastVisits',op('ssPlanEvidence',s('plans'),s('expected'))),'Semantic comparability comes before a work metric. Repeated rows are counted across each supplied scan node.','Invented row-visit counts omit I/O, cache, parallelism and memory effects. They do not predict real execution time.',['Check answer IDs before comparing scan work.'])});

const accessSetup=`CREATE TABLE jobs(id TEXT PRIMARY KEY NOT NULL,tenant TEXT NOT NULL,asset_id TEXT NOT NULL,status TEXT NOT NULL,private_note TEXT);\nINSERT INTO jobs VALUES('J1','north','P7','open','private A'),('J2','south','P8','open','private B'),('J3','north','P9','done','private C');`;
const accessSolution=`CREATE VIEW north_open_jobs AS SELECT id,asset_id,status FROM jobs WHERE tenant='north' AND status='open';\nSELECT id,asset_id,status FROM north_open_jobs ORDER BY id;`;
const bindSolution=`import sqlite3

def find_jobs(connection, tenant, asset):
    if not isinstance(tenant, str) or not tenant or not isinstance(asset, str):
        raise ValueError("Use a trusted tenant and text asset identifier")
    return connection.execute(
        "SELECT id FROM jobs WHERE tenant = ? AND asset_id = ? ORDER BY id",
        (tenant, asset),
    ).fetchall()

db = sqlite3.connect(":memory:")
db.execute("CREATE TABLE jobs(id TEXT, tenant TEXT, asset_id TEXT)")
db.executemany("INSERT INTO jobs VALUES(?,?,?)", [("J1","north","P7"),("J2","south","P7")])
print(find_jobs(db, "north", "P7"))`;
const permissions=sqlLesson({id:'sql-parameters-permissions',title:'Let a Search Value Stay a Value',topic:'Making Queries Practical',blurb:'A search box should select an asset, not rewrite the query or change whose records are visible. Keep values, query structure and permissions at separate boundaries.',openingTitle:'An Asset Search Should Not Become a New SQL Command',opening:['A technician types an asset name into a search box. The application pastes it into a SQL string. A quote in that name can change how the database reads the statement instead of remaining ordinary text.','We will bind values through the database driver, keep the tenant scope supplied by trusted application state, and expose only the fields the interface needs. The SQLite exercise demonstrates a scoped view; a deployed service also needs real database and application permissions.'],prerequisites:[before('Filtering rows','sql-where'),before('Schemas and identities','sql-schema-design')],history:history('Separating Query Structure from Supplied Data',[S('Python sqlite3 parameter substitution','https://docs.python.org/3/library/sqlite3.html'),postgres('PostgreSQL privileges','ddl-priv'),postgres('PostgreSQL row security','ddl-rowsecurity')],'Database applications needed to reuse a query while supplying different values. Driver parameter interfaces separate those values from SQL structure. That same boundary prevents a value containing SQL punctuation from being reinterpreted as part of the query when used correctly.','Database access control developed alongside shared data systems because syntactically valid queries can still access the wrong records. Parameter binding and authorisation solve different problems. Botie’s maintenance search needs both, even though our isolated browser database has no production users or server roles.'),reading:reading('Does the selected asset belong to the trusted tenant?','Filter the record set by trusted tenant scope before matching the supplied asset value.','Parameter binding does not grant permission','Practice. Expose the permitted job fields','Visible job IDs'),intuition:[flow('Keep the source of each input visible','Two values enter the query from different trust boundaries.',[['Authenticated request','Trusted tenant: north'],['Search box','Supplied asset: P7'],['Query structure','Fixed tenant and asset predicates'],['Driver binding','Both values remain data'],['Result projection','Only fields the interface needs']], 'A user-supplied tenant field cannot replace the authenticated scope simply because it is safely parameterised.')],technicalPart:3,checkpointAfter:2,parts:[p('Keep a query’s shape separate from its values','The query structure says which table and fields are involved and how rows are filtered. The asset name is a value placed into that fixed structure. Driver placeholders preserve that distinction.\n\nManually adding quotation marks or escaping a few characters is easy to get wrong across dialects and encodings. Use the driver’s binding API. A parameter containing a quote or SQL-looking text is then compared as a value rather than becoming a new predicate.',null,'The exercise uses a local database and harmless fixture strings. It does not connect to any external service.'),p('Trusted scope must come from the application','Binding tenant and asset values prevents them from changing SQL syntax. It does not prove that the caller may choose any tenant. Obtain the tenant from authenticated server-side context and enforce access again at the data boundary appropriate to the service.\n\nDo not place database credentials in a browser worksheet or give a model unrestricted SQL access because its outputs pass a schema check. A model-generated query is still code whose available operations and data access need deliberate limits.',null,'The workshop shows exact record matching. It does not interpret strings as SQL commands.'),p('Bind values through Python sqlite3','Python sqlite3 accepts placeholders such as ? and a separate parameter sequence. A single parameter still needs a one-item sequence. fetchall returns a list of row tuples in the requested order.\n\nThe programming exercise writes find_jobs(connection, tenant, asset). Its tenant argument represents scope already established by the caller; the function does not implement login or authorisation. The SQL string remains fixed while the parameters change.',null,'Placeholder spelling varies between database drivers. Follow the driver used by the application.',[{title:'A quoted identifier remains ordinary data',paragraphs:['This complete local program searches for a value containing a quote.'],code:'import sqlite3\nconnection = sqlite3.connect(":memory:")\nconnection.execute("CREATE TABLE assets(id TEXT)")\nconnection.execute("INSERT INTO assets VALUES(?)", ("P\'7",))\nprint(connection.execute("SELECT id FROM assets WHERE id = ?", ("P\'7",)).fetchall())',output:'[("P\'7",)]',interpretation:['The quote belongs to the stored value and does not alter the SQL statement.']}]),p('Identifiers need a different choice mechanism','A value placeholder does not generally substitute a table name, column name or sort-direction keyword. If the interface offers a sort order, map its allowed choices to known query fragments or use the driver’s supported identifier-composition API.\n\nDo not convert an arbitrary submitted string into a column identifier and assume value binding elsewhere protects it. Keep the list of accessible fields narrow. The safe design depends on which parts are data and which parts would change executable structure.',null,'An allowlist chooses among known structural options. It is not an attempt to sanitise arbitrary SQL.'),p('Expose a smaller read surface','Our SQL exercise creates a view containing only north’s open jobs and the fields used by the queue. It demonstrates projection and a stable predicate in one named relation. Inspecting the view makes accidental private_note inclusion easy to notice.\n\nSQLite does not provide PostgreSQL-style server users and GRANT privileges. A local caller with direct access to this database can still read the underlying table. In a server database, appropriate roles and grants can restrict access to the view or approved operations; application checks and, where suitable, row-level security add separate controls.',null,'A view is not an authentication system.',[ex('Return only the fields needed for the queue','This fixed projection leaves internal notes out of the result.',accessSetup,`SELECT id,asset_id,status FROM jobs WHERE tenant='north' AND status='open' ORDER BY id;`,output([['J1','P7','open']]),'The result includes the permitted row and omits private_note. The exercise turns that relation into a named view.')]),p('Give the service only the operations it needs','Use separate credentials or roles for migrations, application writes and read-only reporting where the architecture supports them. A report process rarely needs permission to change schemas. Revoke unnecessary inherited or public grants and inspect effective privileges rather than only the most recent GRANT statement.\n\nPostgreSQL row-level security can constrain visible rows under defined policies, with important ownership and privileged-role exceptions. Treat it as a configured database feature to test, not a promise made by a WHERE clause in one code path.',null,'The browser examples do not configure production roles or claim to demonstrate complete tenant isolation.'),p('Bound the query even when its values are safe','A parameterised query can still be expensive or return too much permitted data. Apply pagination, response-size limits and bounded execution appropriate to the service. Avoid logging secrets or unnecessary row content while retaining enough identifiers to investigate access decisions.\n\nTest a literal quote, an SQL-looking asset name, an absent asset, and the same asset ID in another tenant. Those cases check binding and scoping separately. Operational testing must additionally exercise the actual deployed role and every exposed endpoint.',null,'Correct syntax handling is one necessary boundary in a larger access design.')],checkpoint:[q('The tenant value is safely bound as a parameter, but the browser chooses any tenant it likes.','What is still missing?',['An authorisation boundary for selecting tenant scope','More quotation marks around the tenant','A wider SELECT list'],0,'Binding prevents syntax changes; it does not grant access to another tenant.'),tf('A search value contains a quote and is passed through a driver placeholder.','The quote should remain part of the value.',true,'The driver binds data separately from query structure.')],quiz:[q('The UI offers sort by created time or by asset ID.','How should the server choose that structural SQL fragment?',['Map allowed choices to known column/order fragments','Bind any arbitrary SQL fragment as if it were a value','Paste the submitted string without restriction'],0,'Identifiers and keywords need deliberate structural composition rather than ordinary value binding.'),tf('A SQLite view omits private_note, but the caller can read its base table directly.','The view alone enforces production confidentiality.',false,'A narrower projection needs actual access restrictions on the surrounding data surface.')],practice:[exercise('Can the queue expose only north’s open-job fields?',['Create north_open_jobs as a view returning exactly id,asset_id,status for jobs where tenant is north and status is open. Finish with those fields ordered by id. Do not change or delete base-table rows. This is a scoped relation exercise, not a production permission configuration.'],accessSetup,'-- Create the scoped view and read it.\n',accessSolution,output([['J1','P7','open']]),['A view stores a query definition.','Specify the selected columns rather than using SELECT *.'],[['Visible queue',resultTest([['J1','P7','open']])],['No private field in the view','assert [r[1] for r in db.execute("PRAGMA table_info(north_open_jobs)")] == ["id","asset_id","status"]'],['New rows respect both predicates',variant("INSERT INTO jobs VALUES('J4','north','P2','open','private D'),('J5','south','P2','open','private E');",[['J1','P7','open'],['J4','P2','open']])],['Base data remains available to the isolated test','assert db.execute("SELECT COUNT(*) FROM jobs").fetchone()[0] == 3']]),challenge('Can an asset value stay data at the driver boundary?',['Write find_jobs(connection, tenant, asset). Return sorted one-column row tuples containing IDs whose tenant and asset_id both match. Require a nonempty tenant string and a string asset; otherwise raise ValueError. Use sqlite3 parameter binding. The caller supplies an already trusted tenant. Print the supplied north/P7 lookup.'], 'import sqlite3\n\ndef find_jobs(connection, tenant, asset):\n    pass\n\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE jobs(id TEXT, tenant TEXT, asset_id TEXT)")\ndb.executemany("INSERT INTO jobs VALUES(?,?,?)", [("J1","north","P7"),("J2","south","P7")])\nprint(find_jobs(db, "north", "P7"))',bindSolution,"[('J1',)]",['Pass the SQL text and values as separate execute arguments.','Keep both scope and asset predicates in the fixed query.'],[['Tenant-scoped match','assert find_jobs(db,"north","P7") == [("J1",)]\nassert find_jobs(db,"south","P7") == [("J2",)]'],['A quote is part of an asset value','db.execute("INSERT INTO jobs VALUES(?,?,?)", ("J3","north","P\'7"))\nassert find_jobs(db,"north","P\'7") == [("J3",)]'],['SQL-looking text cannot widen the result','assert find_jobs(db,"north","\' OR 1=1 --") == []'],['Reject missing scope','try:\n    find_jobs(db,"","P7")\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("A tenant scope is required")']])],build:build('Match a search inside the trusted tenant scope','Two tenants use the same local asset label.','Filter records by the trusted tenant selector, then match the supplied asset selector and return visible job IDs.',{rows:'Job records',scope:'Trusted tenant selector',search:'Supplied asset value'},[sample('North searches for P7',{rows:[{id:'J1',tenant:'north',asset:'P7'},{id:'J2',tenant:'south',asset:'P7'}],scope:{tenant:'north'},search:{asset:'P7'}},['J1']),sample('A different trusted scope',{rows:[{id:'J1',tenant:'north',asset:'P7'},{id:'J2',tenant:'south',asset:'P7'}],scope:{tenant:'south'},search:{asset:'P7'}},['J2']),sample('SQL-looking text remains a literal value',{rows:[{id:'J1',tenant:'north',asset:'P7'}],scope:{tenant:'north'},search:{asset:"' OR 1=1 --"}},[])],op('ssIds',op('ssMatchRows',op('ssMatchRows',s('rows'),s('scope')),s('search'))),'The search is evaluated inside an already scoped set, and exact values never become executable query text.','The widget has no SQL parser and no real login. The Python challenge exercises parameter binding; production permissions need a deployed service design.',['Keep trusted scope distinct from the submitted search value.'])});

const qualitySetup=`CREATE TABLE assets(id TEXT PRIMARY KEY NOT NULL); INSERT INTO assets VALUES('P7'),('P8');\nCREATE TABLE raw_readings(id TEXT,asset_id TEXT,value REAL,event_seq INTEGER,ingest_seq INTEGER);\nINSERT INTO raw_readings VALUES('R1','P7',20,1,2),('R2','P99',25,2,3),('R3','P8',NULL,3,4),('R4','P7',200,6,5),('R1','P7',20,1,2);`;
const qualitySolution=`SELECT id,'duplicate' AS issue FROM raw_readings GROUP BY id HAVING COUNT(*)>1\nUNION\nSELECT r.id,'unknown_asset' FROM raw_readings r LEFT JOIN assets a ON a.id=r.asset_id WHERE a.id IS NULL\nUNION\nSELECT id,'missing_value' FROM raw_readings WHERE value IS NULL\nUNION\nSELECT id,'out_of_range' FROM raw_readings WHERE value<0 OR value>100\nUNION\nSELECT id,'future_event' FROM raw_readings WHERE event_seq>ingest_seq\nORDER BY id,issue;`;
const quality=sqlLesson({id:'sql-data-quality',title:'Which Sensor Records Should Reach the Training Table?',topic:'Keeping Learning Data Trustworthy',blurb:'A query can run successfully over duplicate identities, missing readings and impossible timestamps. Turn the dataset’s assumptions into visible checks before building model features.',openingTitle:'The Training Query Ran, but the Input Was Wrong',opening:['Botie builds a feature table without a SQL error. Later we discover a repeated sensor message, a reading linked to an absent pump and a temperature with the wrong scale. Successful query execution did not establish useful training data.','We will inspect a raw staging table, report every failed contract per reading identity, and keep rejected data available for repair. The rules are explicit so a reader can see what a clean report does and does not establish.'],prerequisites:[before('Feature tables','sql-feature-tables'),before('Constraints','sql-constraints'),before('Set operations','sql-set-operations')],history:history('Checking the Facts Before Combining Them',[codd,postgres('Database constraints','ddl-constraints'),S('TensorFlow Data Validation: Detecting schema and distribution problems','https://www.tensorflow.org/tfx/data_validation/get_started')],'Relational constraints supplied ways to keep declared identities and relationships consistent. Analytical pipelines also receive raw data that must be inspected before it is admitted to those curated tables. A staging area makes it possible to report failed records rather than losing the evidence at the first rejected insert.','Machine-learning data tools later added schema and distribution comparisons to that practice. Our SQL audit addresses selected deterministic rules for invented sensor records. It cannot establish that labels are correct or that a dataset represents the population a model will encounter.'),reading:reading('Which reading identities fail the declared contract?','Check known assets, required readings, range and timing, then expose the failing identities.','A successful SELECT does not validate its inputs','Practice. Report every reading-contract violation','Reading IDs needing review'),intuition:[table('A plausible number can still belong to a bad record','Each row carries identity and timing as well as its measured value.',['Record problem','Why a model pipeline cares','Check'],[['Duplicate reading ID','Repeated evidence changes weighting','Count identities'],['Absent asset','Features attach to no registered entity','Check parent membership'],['Unknown value','Missingness changes the statistic','Test IS NULL'],['Event after ingestion','The stated timeline is inconsistent','Compare declared clocks']], 'The fixture assumes event and ingestion counters share the same clock. Real clock skew needs a documented tolerance.')],technicalPart:3,checkpointAfter:2,parts:[p('Keep raw evidence separate from accepted records','A raw table preserves what arrived and its source identity. A curated table contains records that satisfy the declared contract after any justified transformation. A quarantine or issue table records what failed and why.\n\nDo not silently drop failed rows and report the remaining count as if the original batch were complete. Record accepted and rejected counts, source batch IDs and the rule version. A downstream feature query should know whether a missing interval means no events or an unresolved ingestion failure.',null,'The audit output is part of the dataset, not an incidental debug message.'),p('Check identity before computing aggregates','Duplicate event identities can count the same physical observation twice. Distinct identities with equal temperatures are different observations and should not automatically collapse. Define which source fields identify an event before applying deduplication.\n\nA duplicate ID with conflicting payloads is a different problem from an exact replay. Choose a policy based on source revisions or quarantine the conflict. Taking the first row the database happens to return is not a reproducible rule.',null,'The exercise reports a duplicate identity once, while retaining all issue categories it violates.'),p('Report each violated rule independently','Our audit returns id and issue. Separate SELECT branches identify duplicates, unknown assets, missing values, out-of-range values and future events. UNION makes each identity/reason pair appear once. A single CASE expression would stop after one branch and could hide a second problem on the same record.\n\nThe range is an invented accepted interval in one declared unit. It is inclusive at both ends. NULL is checked separately because ordinary numeric comparisons with NULL do not return true.',null,'Explain the boundary values and clock assumptions beside each rule.',[ex('Find orphaned asset references','A left join keeps the raw record even when the register has no match.',qualitySetup,`SELECT DISTINCT r.id,r.asset_id FROM raw_readings r\nLEFT JOIN assets a ON a.id=r.asset_id WHERE a.id IS NULL ORDER BY r.id;`,output([['R2','P99']]),'The raw row survives for diagnosis. An inner join would hide it from this report.')]),p('Check time relative to the decision being modelled','Event time describes when something happened. Ingestion time describes when the pipeline received it. Prediction time determines whether the information was available for a training example. A historical event that arrived later can be valid raw data while being unavailable to an earlier prediction.\n\nThe simple future-event check only verifies consistency under a shared-clock assumption. It is not a point-in-time feature join. Use the earlier feature-table lesson’s availability conditions when assembling model inputs, and keep label availability separate from feature availability.',null,'A clean range-and-identity audit does not rule out target leakage.'),p('Look beyond individual rows','A batch can satisfy every row constraint while losing half the expected sensors. Monitor freshness, volume, null rates and distribution changes at meaningful groups such as site or device family. Compare these with documented expectations and investigate changes rather than automatically declaring every shift wrong.\n\nA real equipment upgrade can change the measurement distribution. A stale ingestion job can leave a perfectly shaped but obsolete table. SQL summaries provide evidence for these checks; deciding what action to take requires the application’s context.',null,'Choose thresholds from observed operating requirements, and record the uncertainty behind them.'),p('Keep validation reproducible','Store the SQL or rule version, source snapshot, accepted units and data cutoffs with the validation report. Rebuilding a model from today’s corrected table may differ from the data used by the original run. Preserve a versioned snapshot or a reproducible change history when that distinction matters.\n\nTest the audit with simultaneous failures, boundary values and an empty batch. A no-issue output for zero records should not automatically be labelled a healthy delivery. The pipeline also needs a separate completeness expectation.',null,'The incremental lesson will preserve source change position so repairs and replays can be reconciled.')],checkpoint:[q('Two rows share event ID R1. Their values are equal. Another row has a different ID and the same value.','Which equality establishes a duplicate under the declared identity contract?',['The repeated event ID','Every repeated temperature','Every reading from the same asset'],0,'Observation identity and value equality answer different questions.'),tf('A reading violates both the range and timestamp rules.','An audit can legitimately report both issues for that ID.',true,'Independent checks preserve information that a first-match CASE can hide.')],quiz:[q('A historical measurement occurred before prediction time but arrived in the system afterward.','What must the feature join consider?',['Whether the measurement was available by prediction time','Only whether its numeric range is valid','Only its event ID'],0,'Point-in-time availability prevents future-arriving evidence from leaking into an earlier prediction.'),tf('An empty raw batch returns no row-level violations.','That alone proves the expected sensor delivery was healthy.',false,'Completeness and freshness need separate checks.')],practice:[exercise('Can the audit report every problem without hiding a second failure?',['Return distinct (id, issue) pairs ordered by id then issue. Issue names: duplicate when an ID occurs more than once; unknown_asset when asset_id has no match; missing_value for NULL; out_of_range outside inclusive [0,100]; future_event when event_seq exceeds ingest_seq. Report every applicable issue. The counters share a clock in this fixture. Preserve raw rows.'],qualitySetup,'-- Combine independent issue queries and order the report.\n',qualitySolution,output([['R1','duplicate'],['R2','unknown_asset'],['R3','missing_value'],['R4','future_event'],['R4','out_of_range']]),['Use separate branches when one row may violate several rules.','UNION removes duplicate identity/reason pairs. It does not remove different reasons for one ID.'],[['All initial violations',resultTest([['R1','duplicate'],['R2','unknown_asset'],['R3','missing_value'],['R4','future_event'],['R4','out_of_range']])],['Inclusive range boundaries',variant("DELETE FROM raw_readings; INSERT INTO raw_readings VALUES('A','P7',0,1,1),('B','P8',100,1,2);",[])],['Several failures on one identity',variant("DELETE FROM raw_readings; INSERT INTO raw_readings VALUES('X','missing',200,5,4);",[['X','future_event'],['X','out_of_range'],['X','unknown_asset']])],['Raw evidence remains','assert db.execute("SELECT COUNT(*) FROM raw_readings").fetchone()[0] == 5']])],build:build('Find readings that need repair before feature building','A raw sensor batch contains malformed relationships and measurements.','Connect the declared asset list and accepted range to the reading checks, then return identities that failed.',{rows:'Raw reading records',assets:'Registered asset IDs',range:'Inclusive temperature range'},[sample('One unknown asset and one absent measurement',{rows:[{id:'R1',asset_id:'P7',value:20,event_seq:1,ingest_seq:2},{id:'R2',asset_id:'P99',value:20,event_seq:1,ingest_seq:2},{id:'R3',asset_id:'P7',value:null,event_seq:1,ingest_seq:2}],assets:['P7'],range:{min:0,max:100}},['R2','R3']),sample('A future event with a plausible value',{rows:[{id:'R4',asset_id:'P7',value:20,event_seq:6,ingest_seq:5}],assets:['P7'],range:{min:0,max:100}},['R4']),sample('The inclusive boundaries are allowed',{rows:[{id:'R5',asset_id:'P7',value:0,event_seq:1,ingest_seq:1},{id:'R6',asset_id:'P7',value:100,event_seq:1,ingest_seq:2}],assets:['P7'],range:{min:0,max:100}},[])],op('ssFailedIds',op('ssQualityChecks',s('rows'),s('assets'),s('range'))),'Identity, relationship, measurement and time checks all affect whether a raw record can enter this curated set.','The toy contract assumes comparable clocks and a declared unit. It does not prove label truth, representativeness or freedom from leakage.',['A valid temperature still needs a known asset and a consistent timeline.'])});

const incrementSetup=`CREATE TABLE current_readings(id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL,deleted INTEGER NOT NULL,value REAL);\nINSERT INTO current_readings VALUES('R1',1,0,20),('R2',1,0,30);\nCREATE TABLE checkpoint(seq INTEGER NOT NULL); INSERT INTO checkpoint VALUES(10);\nCREATE TABLE changes(seq INTEGER PRIMARY KEY,id TEXT NOT NULL,version INTEGER NOT NULL,deleted INTEGER NOT NULL,value REAL);\nINSERT INTO changes VALUES(11,'R1',2,0,22),(12,'R2',2,1,NULL),(13,'R3',1,0,18);`;
const incrementSolution=`BEGIN;\nINSERT INTO current_readings(id,version,deleted,value)\nSELECT id,version,deleted,value FROM changes WHERE seq>(SELECT seq FROM checkpoint) ORDER BY seq\nON CONFLICT(id) DO UPDATE SET version=excluded.version,deleted=excluded.deleted,value=excluded.value\nWHERE excluded.version>current_readings.version;\nUPDATE checkpoint SET seq=MAX(seq,COALESCE((SELECT MAX(seq) FROM changes),seq));\nCOMMIT;\nSELECT id,version,deleted,value FROM current_readings ORDER BY id;`;
const batch=op('ssAfterCursor',s('changes'),s('cursor'));
const incremental=sqlLesson({id:'sql-incremental-pipelines',title:'Pick Up New Changes Without Losing Late Readings',topic:'Keeping Learning Data Trustworthy',blurb:'Repeated full imports become expensive, but a naive timestamp filter misses corrections and deletions. Track source change position, merge versions and commit the checkpoint with the result.',openingTitle:'Yesterday’s Reading Arrived After Today’s Import Finished',opening:['Botie’s pipeline remembers the latest event time and asks for anything newer on the next run. A delayed sensor message arrives with yesterday’s event time, so it never enters the training source. A later correction has the same problem.','We need to track when the source exposes a change, as well as when its measured event happened. The lesson builds a versioned merge and a checkpoint that can be replayed after a failure.'],prerequisites:[before('Data quality','sql-data-quality'),before('Transactions','sql-transactions'),before('Revision-aware writes','sql-insert-update-delete')],history:history('Remembering a Change Position Instead of Recopying Everything',[postgres('PostgreSQL logical decoding concepts','logicaldecoding-explanation'),sqlite('SQLite UPSERT','lang_upsert'),sqlite('SQLite transactions','lang_transaction')],'Databases maintain change information to recover and coordinate writes. Change-data-capture systems can expose committed changes to downstream consumers instead of forcing every consumer to recopy the full source. PostgreSQL logical decoding is one documented implementation with its own restart, retention and delivery responsibilities.','A consumer still needs a recoverable position and a replay policy. Our source supplies a strictly increasing ingestion sequence and per-record versions. These are explicit teaching contracts; an arbitrary timestamp column does not automatically provide the same guarantees.'),reading:reading('Apply the new source changes and keep their checkpoint','Select changes after the committed cursor, merge each identity by version, then keep resulting state and cursor together.','A checkpoint must describe the data that was actually committed','Practice. Merge a replayable change batch','Versioned state and source cursor'),intuition:[table('The two orderings answer different questions','A late event can be a newly delivered change.',['Change sequence','Event meaning','Consumer action'],[['11','Correction to earlier R1','Update R1 to its newer version'],['12','R2 was deleted','Retain a tombstone for R2'],['13','A delayed new reading R3','Insert R3 even if its event time is old']], 'The cursor follows source delivery order. Per-record version decides whether a payload is newer.')],technicalPart:3,checkpointAfter:2,parts:[p('Separate event time, arrival order and record version','Event time belongs to the measured phenomenon. Arrival order describes when a change becomes available to the pipeline. Version orders successive states of one identity. A late event can have an old event time and a new arrival sequence.\n\nOur source guarantees unique increasing sequence values and monotonic versions per identity. A production source must document its ordering, transaction and retention behaviour. A poll over updated_at needs careful tie handling and cannot detect hard deletions unless another mechanism records them.',null,'Do not turn MAX(event_time) into a reliable ingestion cursor by naming it a watermark.'),p('Define exactly what the checkpoint means','The checkpoint is the last source change position whose effects are committed in the sink. Read only later positions for the next batch. If the sink commits data but loses the checkpoint update, a replay can occur. If the checkpoint commits first, a crash can skip data that was never written.\n\nCommit both in one transaction when they share a database. Across systems, use a delivery protocol and idempotent merge that tolerate replay, and reconcile partial outcomes. Exactly-once claims require specifying the entire boundary and its assumptions.',null,'The exercise’s checkpoint table and current table share one SQLite transaction.'),p('Merge identities by version','A stable primary key identifies the record. A newer version replaces its stored payload; an older version does not. Replaying an equal version with the same payload leaves the result unchanged.\n\nThe exercise assumes equal versions always carry equal payloads because conflicting records have already been quarantined. A real pipeline must check that contract. Choosing a random last arrival for equal conflicting versions destroys reproducibility. The workshop rejects that conflict explicitly.',null,'Source position and record version solve different ordering problems.',[ex('Keep a newer value when an old revision arrives','A delayed old payload should not replace the current row.',incrementSetup,`INSERT INTO current_readings VALUES('R1',0,0,99)\nON CONFLICT(id) DO UPDATE SET version=excluded.version,value=excluded.value\nWHERE excluded.version>current_readings.version;\nSELECT id,version,value FROM current_readings WHERE id='R1';`,output([['R1',1,20]]),'The old version is ignored even though it was delivered now.')]),p('Represent deletion as a versioned change','If a deleted identity simply disappears from a snapshot, an incremental consumer may never learn what to remove. A deletion event or tombstone tells the sink that this identity was deliberately removed at a particular version.\n\nRetaining that tombstone prevents an older late update from recreating the deleted record. Our current_readings table stores deleted as 0 or 1 and keeps a NULL value for a tombstone. Readers of active data must explicitly filter deleted=0. Tombstone retention needs to cover the source’s replay and late-arrival assumptions.',null,'A deletion is data about an identity. It is not equivalent to a missing sensor value.'),p('Advance over ignored old versions too','A batch may contain an arrival whose version is older than the current record. Its payload is ignored, but its source position was still processed. Advance the cursor past it once the batch commits. Otherwise the consumer may read the same obsolete change indefinitely.\n\nAn empty batch leaves the cursor unchanged. Never move a checkpoint backwards because an old source extract was supplied. The SQL exercise uses the greater of the previous checkpoint and the maximum available change sequence.',null,'The resulting cursor describes processed delivery positions, not only rows whose values changed.'),p('Bound a batch without skipping changes that share a timestamp','A busy source can keep producing changes while the consumer works. Capture a source-supported upper position for the batch, then read positions after the committed cursor up to that bound. Commit the result before starting the next interval. The source must retain the interval and expose complete changes within it; reading an arbitrary MAX from a changing business table does not establish those properties.\n\nTimestamp polling adds another problem. If two rows share the final timestamp and a row limit splits them, resuming with only updated_at greater than that timestamp skips the remaining row. An ordered timestamp-and-identity cursor can paginate a stable set, but it still cannot detect a later change that reuses an earlier timestamp. Reliable polling needs a source contract, an overlap-and-deduplication policy where suitable, or a change log. Our teaching input uses unique source sequence numbers so that these assumptions are visible.',null,'The exercise receives a complete finite extract. A production reader must additionally define how it obtains and retains a complete bounded interval.'),p('Plan for backfills and late corrections','A historical backfill may revisit a time range already represented in features. Give it a declared source snapshot and transformation version, and merge by stable identity or rebuild a partition deliberately. Do not mix a backfill cursor into the live stream unless its ordering contract supports that.\n\nCorrections can invalidate previously built aggregates or training examples. Decide whether to recompute affected partitions, keep immutable historical snapshots, or publish a new dataset version. Retain enough lineage to explain which source revisions produced a model’s features.',null,'Idempotent row merging does not automatically refresh every derived aggregate downstream.'),p('Notice when the source no longer has the required history','Suppose the sink stopped at change position 100, but the source has already discarded everything before 150. Resuming at 150 would silently omit an interval. The consumer needs to detect that its checkpoint is older than the retained history and take a documented recovery path.\n\nA new full snapshot can rebuild the sink, but the snapshot and following change stream need a consistent handoff position. Otherwise changes that occur during the copy can be missed or duplicated. Preserve the old dataset version while rebuilding when it is needed for model reproducibility. Reconcile the rebuilt state before directing readers to it.',null,'A successful connection does not prove that the source can still replay the interval the sink needs.'),p('Reconcile the incremental result with a complete view','Periodically compare record counts, keys and selected aggregates against a trusted source snapshot. Missing change retention, a broken cursor or a source schema change can produce a plausible but incomplete sink. Monitor lag and checkpoint progress separately from job success messages.\n\nThe final challenge replays a batch, introduces an older version after a deletion, and tests an empty source extract. These are ordinary recovery cases to design before the first production outage.',null,'The pipeline is ready for the next lesson when its checkpoint and data tell the same story after a restart.')],checkpoint:[q('A reading occurred yesterday but arrives today with a new source change sequence. The consumer tracks only maximum event time.','What can go wrong?',['The late reading can be skipped','The old event time automatically becomes today','The query necessarily raises an error'],0,'Event-time ordering does not represent when data became available to the pipeline.'),tf('A data batch and its cursor share one database.','Committing them in one transaction avoids publishing a checkpoint for uncommitted sink changes.',true,'The checkpoint and its effects form one recoverable unit.')],quiz:[q('R2 is deleted at version 5. A late update for R2 arrives at version 3.','Why retain the version-5 tombstone?',['It prevents the older update from resurrecting R2','It makes the old value a new observation','It removes the need for any cursor'],0,'The tombstone preserves the latest identity state for future version comparisons.'),tf('A batch processes a new source sequence whose record version is older than the stored version.','The cursor must remain before that sequence because the payload was ignored.',false,'The position was processed even though it did not change the record. It can be checkpointed with the batch.')],practice:[exercise('Can a change batch survive replay and preserve deletion?', ['Inside one transaction, apply changes with seq greater than the single checkpoint.seq. Insert new identities and update existing ones only for a greater version. Keep tombstones in current_readings. Advance checkpoint to the greatest processed available sequence without moving backwards, then commit. Return id,version,deleted,value ordered by id. The source guarantees unique sequences, nonnegative versions, and identical payloads for equal versions.'],incrementSetup,'-- Merge changes and checkpoint them in the same transaction.\n',incrementSolution,output([['R1',2,0,22],['R2',2,1,null],['R3',1,0,18]]),['The source sequence filters the batch; the record version controls replacement.','Keep deletion rows so older versions cannot recreate them.'],[['Merged rows',resultTest([['R1',2,0,22],['R2',2,1,null],['R3',1,0,18]])],['Committed source position','assert db.execute("SELECT seq FROM checkpoint").fetchone()[0] == 13\nassert not db.in_transaction'],['Replayed batch is stable','assert query_rows(sql, setup_sql + sql) == rows'],['A late older version cannot undo deletion',variant("INSERT INTO changes VALUES(14,'R2',1,0,88);",[['R1',2,0,22],['R2',2,1,null],['R3',1,0,18]])],['An empty extract leaves current state',variant('DELETE FROM changes;',[['R1',1,0,20],['R2',1,0,30]])]])],build:build('Checkpoint a versioned maintenance-reading batch','A source delivers corrections, deletions and late records after the last committed position.','Select later change positions, apply the newest version per identity, and combine resulting state with the advanced cursor.',{state:'Stored versioned readings',changes:'Incoming source changes',cursor:'Committed ingestion sequence'},[sample('A correction and a deletion arrive',{state:[{id:'R1',version:1,deleted:false,value:20},{id:'R2',version:1,deleted:false,value:30}],changes:[{seq:11,id:'R1',version:2,deleted:false,value:22},{seq:12,id:'R2',version:2,deleted:true,value:null}],cursor:10},{state:[{id:'R1',version:2,deleted:false,value:22},{id:'R2',version:2,deleted:true,value:null}],cursor:12}),sample('An older arrival cannot undo a tombstone',{state:[{id:'R2',version:2,deleted:true,value:null}],changes:[{seq:13,id:'R2',version:1,deleted:false,value:30}],cursor:12},{state:[{id:'R2',version:2,deleted:true,value:null}],cursor:13}),sample('An empty batch preserves the checkpoint',{state:[{id:'R1',version:1,deleted:false,value:20}],changes:[],cursor:10},{state:[{id:'R1',version:1,deleted:false,value:20}],cursor:10})],op('ssCheckpoint',op('ssApplyChanges',s('state'),batch),op('ssAdvanceCursor',batch,s('cursor'))),'A record’s version determines its stored state, while the processed source sequence determines the next ingestion point.','The widget returns a checkpoint record but does not persist it. The SQL exercise demonstrates atomic sink/cursor commit in one isolated database.',['Use the same filtered batch for both the state merge and cursor advance.'])});

